export const EXTRA = [
{"id":"fe_7ee918c7","n":"90/90 hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."],"src":"fedb","img":"fedb/90_90_Hamstring/0.jpg","img2":"fedb/90_90_Hamstring/1.jpg"},
{"id":"fe_6a412386","n":"adductor","bp":"upper legs","eq":"roller","tg":"adductors","sm":[],"st":["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."],"src":"fedb","img":"fedb/Adductor/0.jpg","img2":"fedb/Adductor/1.jpg"},
{"id":"fe_93c058e5","n":"adductor/groin","bp":"upper legs","eq":"body weight","tg":"adductors","sm":[],"st":["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"src":"fedb","img":"fedb/Adductor_Groin/0.jpg","img2":"fedb/Adductor_Groin/1.jpg"},
{"id":"fe_145fc5c5","n":"alternate leg diagonal bound","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."],"src":"fedb","img":"fedb/Alternate_Leg_Diagonal_Bound/0.jpg","img2":"fedb/Alternate_Leg_Diagonal_Bound/1.jpg"},
{"id":"fe_9ed54def","n":"alternating deltoid raise","bp":"shoulders","eq":"dumbbell","tg":"delts","sm":[],"st":["In a standing position, hold a pair of dumbbells at your side.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","Return the weights to your side.","On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","Return the weights to the starting position and continue alternating to the front and side."],"src":"fedb","img":"fedb/Alternating_Deltoid_Raise/0.jpg","img2":"fedb/Alternating_Deltoid_Raise/1.jpg"},
{"id":"fe_83ba823f","n":"ankle on the knee","bp":"upper legs","eq":"body weight","tg":"glutes","sm":[],"st":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"src":"fedb","img":"fedb/Ankle_On_The_Knee/0.jpg","img2":"fedb/Ankle_On_The_Knee/1.jpg"},
{"id":"fe_d869346a","n":"anterior tibialis-smr","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"src":"fedb","img":"fedb/Anterior_Tibialis-SMR/0.jpg","img2":"fedb/Anterior_Tibialis-SMR/1.jpg"},
{"id":"fe_a1a83fa2","n":"arm circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"src":"fedb","img":"fedb/Arm_Circles/0.jpg","img2":"fedb/Arm_Circles/1.jpg"},
{"id":"fe_96c2542c","n":"atlas stone trainer","bp":"back","eq":"weighted","tg":"spine","mg":"biceps","sm":["biceps","forearms","glutes","hamstrings","quadriceps"],"st":["This trainer is effective for developing Atlas Stone strength for those who don't have access to stones, and are typically made from bar ends or heavy pipe.","Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.","Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.","Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions."],"src":"fedb","img":"fedb/Atlas_Stone_Trainer/0.jpg","img2":"fedb/Atlas_Stone_Trainer/1.jpg"},
{"id":"fe_e14c40b0","n":"atlas stones","bp":"back","eq":"weighted","tg":"spine","mg":"abdominals","sm":["abdominals","inner thighs","biceps","calves","forearms","glutes","hamstrings","upper back","quadriceps","traps"],"st":["Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.","Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.","As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.","Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible."],"src":"fedb","img":"fedb/Atlas_Stones/0.jpg","img2":"fedb/Atlas_Stones/1.jpg"},
{"id":"fe_3b9c3300","n":"axle deadlift","bp":"back","eq":"barbell","tg":"spine","mg":"forearms","sm":["forearms","glutes","hamstrings","upper back","quadriceps","traps"],"st":["Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"src":"fedb","img":"fedb/Axle_Deadlift/0.jpg","img2":"fedb/Axle_Deadlift/1.jpg"},
{"id":"fe_36f82b2e","n":"back flyes - with bands","bp":"shoulders","eq":"band","tg":"delts","mg":"upper back","sm":["upper back","triceps"],"st":["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Back_Flyes_-_With_Bands/0.jpg","img2":"fedb/Back_Flyes_-_With_Bands/1.jpg"},
{"id":"fe_5cf97810","n":"backward drag","bp":"upper legs","eq":"weighted","tg":"quads","mg":"calves","sm":["calves","forearms","glutes","hamstrings","lower back"],"st":["Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.","Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible."],"src":"fedb","img":"fedb/Backward_Drag/0.jpg","img2":"fedb/Backward_Drag/1.jpg"},
{"id":"fe_600d2dda","n":"backward medicine ball throw","bp":"shoulders","eq":"medicine ball","tg":"delts","sm":[],"st":["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."],"src":"fedb","img":"fedb/Backward_Medicine_Ball_Throw/0.jpg","img2":"fedb/Backward_Medicine_Ball_Throw/1.jpg"},
{"id":"fe_355b0511","n":"ball leg curl","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."],"src":"fedb","img":"fedb/Ball_Leg_Curl/0.jpg","img2":"fedb/Ball_Leg_Curl/1.jpg"},
{"id":"fe_ee435c8e","n":"band good morning","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."],"src":"fedb","img":"fedb/Band_Good_Morning/0.jpg","img2":"fedb/Band_Good_Morning/1.jpg"},
{"id":"fe_e7aaa024","n":"band good morning (pull through)","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.","Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.","Return to the starting position be driving through with the hips to come back to a standing position."],"src":"fedb","img":"fedb/Band_Good_Morning_Pull_Through/0.jpg","img2":"fedb/Band_Good_Morning_Pull_Through/1.jpg"},
{"id":"fe_221f9f3f","n":"band hip adductions","bp":"upper legs","eq":"band","tg":"adductors","sm":[],"st":["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."],"src":"fedb","img":"fedb/Band_Hip_Adductions/0.jpg","img2":"fedb/Band_Hip_Adductions/1.jpg"},
{"id":"fe_c5980115","n":"band pull apart","bp":"shoulders","eq":"band","tg":"delts","mg":"upper back","sm":["upper back","traps"],"st":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"src":"fedb","img":"fedb/Band_Pull_Apart/0.jpg","img2":"fedb/Band_Pull_Apart/1.jpg"},
{"id":"fe_b768feb9","n":"band skull crusher","bp":"upper arms","eq":"band","tg":"triceps","sm":[],"st":["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."],"src":"fedb","img":"fedb/Band_Skull_Crusher/0.jpg","img2":"fedb/Band_Skull_Crusher/1.jpg"},
{"id":"fe_2253e51d","n":"barbell ab rollout","bp":"waist","eq":"barbell","tg":"abs","mg":"lower back","sm":["lower back","shoulders"],"st":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don't, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Barbell_Ab_Rollout/0.jpg","img2":"fedb/Barbell_Ab_Rollout/1.jpg"},
{"id":"fe_1b6b374d","n":"barbell curls lying against an incline","bp":"upper arms","eq":"barbell","tg":"biceps","sm":[],"st":["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.","After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Barbell_Curls_Lying_Against_An_Incline/0.jpg","img2":"fedb/Barbell_Curls_Lying_Against_An_Incline/1.jpg"},
{"id":"fe_c3cd5826","n":"barbell hip thrust","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"calves","sm":["calves","hamstrings"],"st":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."],"src":"fedb","img":"fedb/Barbell_Hip_Thrust/0.jpg","img2":"fedb/Barbell_Hip_Thrust/1.jpg"},
{"id":"fe_55548916","n":"barbell rollout from bench","bp":"waist","eq":"barbell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","lats","shoulders"],"st":["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."],"src":"fedb","img":"fedb/Barbell_Rollout_from_Bench/0.jpg","img2":"fedb/Barbell_Rollout_from_Bench/1.jpg"},
{"id":"fe_ad80b92c","n":"barbell shrug behind the back","bp":"back","eq":"barbell","tg":"traps","mg":"forearms","sm":["forearms","upper back"],"st":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Barbell_Shrug_Behind_The_Back/0.jpg","img2":"fedb/Barbell_Shrug_Behind_The_Back/1.jpg"},
{"id":"fe_7129ad50","n":"barbell side bend","bp":"waist","eq":"barbell","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Barbell_Side_Bend/0.jpg","img2":"fedb/Barbell_Side_Bend/1.jpg"},
{"id":"fe_bdf36d05","n":"barbell walking lunge","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"src":"fedb","img":"fedb/Barbell_Walking_Lunge/0.jpg","img2":"fedb/Barbell_Walking_Lunge/1.jpg"},
{"id":"fe_9d024c46","n":"bear crawl sled drags","bp":"upper legs","eq":"weighted","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.","Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance."],"src":"fedb","img":"fedb/Bear_Crawl_Sled_Drags/0.jpg","img2":"fedb/Bear_Crawl_Sled_Drags/1.jpg"},
{"id":"fe_f7389a76","n":"bench jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.","Perform a short squat in preparation for the jump; swing your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Jump over the bench, landing with the knees bent, absorbing the impact through the legs.","Turn around and face the opposite direction, then jump back over the bench."],"src":"fedb","img":"fedb/Bench_Jump/0.jpg","img2":"fedb/Bench_Jump/1.jpg"},
{"id":"fe_a0de7c59","n":"bench sprint","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Push off with your foot on top of the bench, extending through the hip and knee.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."],"src":"fedb","img":"fedb/Bench_Sprint/0.jpg","img2":"fedb/Bench_Sprint/1.jpg"},
{"id":"fe_6a512480","n":"bent over dumbbell rear delt raise with head on bench","bp":"shoulders","eq":"dumbbell","tg":"delts","sm":[],"st":["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."],"src":"fedb","img":"fedb/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg","img2":"fedb/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg"},
{"id":"fe_65fca891","n":"bent over low-pulley side lateral","bp":"shoulders","eq":"cable","tg":"delts","mg":"lower back","sm":["lower back","upper back","traps"],"st":["Select a weight and hold the handle of the low pulley with your right hand.","Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.","Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.","Slowly lower the weight back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and repeat the movement with the other arm."],"src":"fedb","img":"fedb/Bent_Over_Low-Pulley_Side_Lateral/0.jpg","img2":"fedb/Bent_Over_Low-Pulley_Side_Lateral/1.jpg"},
{"id":"fe_9d0cada2","n":"bent over two-arm long bar row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg","img2":"fedb/Bent_Over_Two-Arm_Long_Bar_Row/1.jpg"},
{"id":"fe_02571964","n":"bicycling","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","sm":[],"st":["To begin, seat yourself on the bike and adjust the seat to your height."],"src":"fedb","img":"fedb/Bicycling/0.jpg","img2":"fedb/Bicycling/1.jpg"},
{"id":"fe_56ee0dd4","n":"board press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","forearms","lats","shoulders"],"st":["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6's, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"src":"fedb","img":"fedb/Board_Press/0.jpg","img2":"fedb/Board_Press/1.jpg"},
{"id":"fe_309f232f","n":"bodyweight flyes","bp":"chest","eq":"ez barbell","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.","Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.","Place your hands on the bars. This will be your starting position.","Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.","After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement."],"src":"fedb","img":"fedb/Bodyweight_Flyes/0.jpg","img2":"fedb/Bodyweight_Flyes/1.jpg"},
{"id":"fe_73f61259","n":"bodyweight squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"src":"fedb","img":"fedb/Bodyweight_Squat/0.jpg","img2":"fedb/Bodyweight_Squat/1.jpg"},
{"id":"fe_cefcfc24","n":"box jump (multiple response)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","inner thighs","calves","quadriceps"],"st":["Assume a relaxed stance facing the box or platform approximately an arm's length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."],"src":"fedb","img":"fedb/Box_Jump_Multiple_Response/0.jpg","img2":"fedb/Box_Jump_Multiple_Response/1.jpg"},
{"id":"fe_03380345","n":"box skip","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","inner thighs","calves","quadriceps"],"st":["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."],"src":"fedb","img":"fedb/Box_Skip/0.jpg","img2":"fedb/Box_Skip/1.jpg"},
{"id":"fe_39d29d43","n":"box squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"inner thighs","sm":["inner thighs","calves","glutes","hamstrings","lower back"],"st":["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"src":"fedb","img":"fedb/Box_Squat/0.jpg","img2":"fedb/Box_Squat/1.jpg"},
{"id":"fe_93f021f2","n":"brachialis-smr","bp":"upper arms","eq":"roller","tg":"biceps","sm":[],"st":["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."],"src":"fedb","img":"fedb/Brachialis-SMR/0.jpg","img2":"fedb/Brachialis-SMR/1.jpg"},
{"id":"fe_c1d3b963","n":"cable iron cross","bp":"chest","eq":"cable","tg":"pectorals","sm":[],"st":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position.","Keeping the elbows extended, pull your arms straight to your sides.","Return your arms back to the starting position after a pause at the peak contraction.","Continue the movement for the prescribed number of repetitions."],"src":"fedb","img":"fedb/Cable_Iron_Cross/0.jpg","img2":"fedb/Cable_Iron_Cross/1.jpg"},
{"id":"fe_fba8bec9","n":"calf-machine shoulder shrug","bp":"back","eq":"leverage machine","tg":"traps","sm":[],"st":["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Calf-Machine_Shoulder_Shrug/0.jpg","img2":"fedb/Calf-Machine_Shoulder_Shrug/1.jpg"},
{"id":"fe_c52fc16d","n":"calf raises - with bands","bp":"lower legs","eq":"band","tg":"calves","sm":[],"st":["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Calf_Raises_-_With_Bands/0.jpg","img2":"fedb/Calf_Raises_-_With_Bands/1.jpg"},
{"id":"fe_979b52dd","n":"calves-smr","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"src":"fedb","img":"fedb/Calves-SMR/0.jpg","img2":"fedb/Calves-SMR/1.jpg"},
{"id":"fe_38e0ed51","n":"car deadlift","bp":"upper legs","eq":"weighted","tg":"quads","mg":"forearms","sm":["forearms","glutes","hamstrings","lower back","traps"],"st":["This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.","Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the floor."],"src":"fedb","img":"fedb/Car_Deadlift/0.jpg","img2":"fedb/Car_Deadlift/1.jpg"},
{"id":"fe_7617a80b","n":"car drivers","bp":"shoulders","eq":"barbell","tg":"delts","mg":"forearms","sm":["forearms"],"st":["While standing upright, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.","Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.","Reverse the motion, turning it all the way to the opposite side.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Car_Drivers/0.jpg","img2":"fedb/Car_Drivers/1.jpg"},
{"id":"fe_0e398d77","n":"carioca quick step","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"abdominals","sm":["abdominals","glutes","calves","hamstrings","quadriceps"],"st":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."],"src":"fedb","img":"fedb/Carioca_Quick_Step/0.jpg","img2":"fedb/Carioca_Quick_Step/1.jpg"},
{"id":"fe_efa54bbb","n":"cat stretch","bp":"back","eq":"body weight","tg":"spine","mg":"upper back","sm":["upper back","traps"],"st":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"src":"fedb","img":"fedb/Cat_Stretch/0.jpg","img2":"fedb/Cat_Stretch/1.jpg"},
{"id":"fe_389668ed","n":"chain handle extension","bp":"upper arms","eq":"weighted","tg":"triceps","sm":[],"st":["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."],"src":"fedb","img":"fedb/Chain_Handle_Extension/0.jpg","img2":"fedb/Chain_Handle_Extension/1.jpg"},
{"id":"fe_4701f750","n":"chain press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.","Lower the chains by flexing the elbows, unloading some of the chain onto the floor.","Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout."],"src":"fedb","img":"fedb/Chain_Press/0.jpg","img2":"fedb/Chain_Press/1.jpg"},
{"id":"fe_d6a43a86","n":"chair upper body stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest"],"st":["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds."],"src":"fedb","img":"fedb/Chair_Upper_Body_Stretch/0.jpg","img2":"fedb/Chair_Upper_Body_Stretch/1.jpg"},
{"id":"fe_980f74fc","n":"child's pose","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","upper back"],"st":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"src":"fedb","img":"fedb/Childs_Pose/0.jpg","img2":"fedb/Childs_Pose/1.jpg"},
{"id":"fe_afede2f4","n":"chin to chest stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"traps","sm":["traps"],"st":["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds."],"src":"fedb","img":"fedb/Chin_To_Chest_Stretch/0.jpg","img2":"fedb/Chin_To_Chest_Stretch/1.jpg"},
{"id":"fe_d7839951","n":"circus bell","bp":"shoulders","eq":"weighted","tg":"delts","mg":"forearms","sm":["forearms","glutes","hamstrings","lower back","traps","triceps"],"st":["The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.","Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.","Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.","Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor."],"src":"fedb","img":"fedb/Circus_Bell/0.jpg","img2":"fedb/Circus_Bell/1.jpg"},
{"id":"fe_a708b446","n":"clean","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"calves","sm":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"st":["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"src":"fedb","img":"fedb/Clean/0.jpg","img2":"fedb/Clean/1.jpg"},
{"id":"fe_c84620de","n":"clean deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"forearms","sm":["forearms","glutes","lower back","upper back","quadriceps","traps"],"st":["Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.","Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar's path.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."],"src":"fedb","img":"fedb/Clean_Deadlift/0.jpg","img2":"fedb/Clean_Deadlift/1.jpg"},
{"id":"fe_30711b62","n":"clean pull","bp":"upper legs","eq":"barbell","tg":"quads","mg":"forearms","sm":["forearms","glutes","hamstrings","lower back","traps"],"st":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."],"src":"fedb","img":"fedb/Clean_Pull/0.jpg","img2":"fedb/Clean_Pull/1.jpg"},
{"id":"fe_6c25c740","n":"clean shrug","bp":"back","eq":"barbell","tg":"traps","mg":"forearms","sm":["forearms","shoulders"],"st":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down."],"src":"fedb","img":"fedb/Clean_Shrug/0.jpg","img2":"fedb/Clean_Shrug/1.jpg"},
{"id":"fe_cd806e69","n":"clean and jerk","bp":"shoulders","eq":"barbell","tg":"delts","mg":"abdominals","sm":["abdominals","glutes","hamstrings","lower back","quadriceps","traps","triceps"],"st":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.","The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."],"src":"fedb","img":"fedb/Clean_and_Jerk/0.jpg","img2":"fedb/Clean_and_Jerk/1.jpg"},
{"id":"fe_d36894f8","n":"clean from blocks","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders","traps"],"st":["With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.","As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep."],"src":"fedb","img":"fedb/Clean_from_Blocks/0.jpg","img2":"fedb/Clean_from_Blocks/1.jpg"},
{"id":"fe_0d33a637","n":"conan's wheel","bp":"upper legs","eq":"weighted","tg":"quads","mg":"abdominals","sm":["abdominals","biceps","calves","forearms","lower back","shoulders","traps"],"st":["With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.","Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns."],"src":"fedb","img":"fedb/Conans_Wheel/0.jpg","img2":"fedb/Conans_Wheel/1.jpg"},
{"id":"fe_63a03475","n":"cross over - with bands","bp":"chest","eq":"band","tg":"pectorals","mg":"biceps","sm":["biceps","shoulders"],"st":["Secure an exercise band around a stationary post.","While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.","Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.","Slowly return to the starting position as you inhale.","Perform for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Cross_Over_-_With_Bands/0.jpg","img2":"fedb/Cross_Over_-_With_Bands/1.jpg"},
{"id":"fe_8146683f","n":"crossover reverse lunge","bp":"back","eq":"body weight","tg":"spine","mg":"abdominals","sm":["abdominals","glutes","hamstrings","quadriceps"],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."],"src":"fedb","img":"fedb/Crossover_Reverse_Lunge/0.jpg","img2":"fedb/Crossover_Reverse_Lunge/1.jpg"},
{"id":"fe_9eaee395","n":"crucifix","bp":"shoulders","eq":"weighted","tg":"delts","mg":"forearms","sm":["forearms"],"st":["In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.","Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds."],"src":"fedb","img":"fedb/Crucifix/0.jpg","img2":"fedb/Crucifix/1.jpg"},
{"id":"fe_afeccc9e","n":"crunch - legs on exercise ball","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Crunch_-_Legs_On_Exercise_Ball/0.jpg","img2":"fedb/Crunch_-_Legs_On_Exercise_Ball/1.jpg"},
{"id":"fe_27f52397","n":"dancer's stretch","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes"],"st":["Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."],"src":"fedb","img":"fedb/Dancers_Stretch/0.jpg","img2":"fedb/Dancers_Stretch/1.jpg"},
{"id":"fe_d44f1dbe","n":"deadlift with chains","bp":"back","eq":"barbell","tg":"spine","mg":"forearms","sm":["forearms","glutes","hamstrings","upper back","quadriceps","traps"],"st":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"src":"fedb","img":"fedb/Deadlift_with_Chains/0.jpg","img2":"fedb/Deadlift_with_Chains/1.jpg"},
{"id":"fe_7654a3c6","n":"decline close-grip bench to skull crusher","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position as you exhale.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat steps 3-6 until the recommended amount of repetitions is performed."],"src":"fedb","img":"fedb/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg","img2":"fedb/Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg"},
{"id":"fe_19bacbfe","n":"deficit deadlift","bp":"back","eq":"barbell","tg":"spine","mg":"forearms","sm":["forearms","glutes","hamstrings","upper back","quadriceps","traps"],"st":["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"src":"fedb","img":"fedb/Deficit_Deadlift/0.jpg","img2":"fedb/Deficit_Deadlift/1.jpg"},
{"id":"fe_854631ae","n":"depth jump leap","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact."],"src":"fedb","img":"fedb/Depth_Jump_Leap/0.jpg","img2":"fedb/Depth_Jump_Leap/1.jpg"},
{"id":"fe_41f00fac","n":"double leg butt kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."],"src":"fedb","img":"fedb/Double_Leg_Butt_Kick/0.jpg","img2":"fedb/Double_Leg_Butt_Kick/1.jpg"},
{"id":"fe_ccb7b35e","n":"downward facing balance","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"abdominals","sm":["abdominals","hamstrings"],"st":["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."],"src":"fedb","img":"fedb/Downward_Facing_Balance/0.jpg","img2":"fedb/Downward_Facing_Balance/1.jpg"},
{"id":"fe_a379dd4d","n":"drop push","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."],"src":"fedb","img":"fedb/Drop_Push/0.jpg","img2":"fedb/Drop_Push/1.jpg"},
{"id":"fe_3a88fabe","n":"dumbbell floor press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."],"src":"fedb","img":"fedb/Dumbbell_Floor_Press/0.jpg","img2":"fedb/Dumbbell_Floor_Press/1.jpg"},
{"id":"fe_bcca803e","n":"dumbbell scaption","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps"],"st":["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."],"src":"fedb","img":"fedb/Dumbbell_Scaption/0.jpg","img2":"fedb/Dumbbell_Scaption/1.jpg"},
{"id":"fe_ec5e03d4","n":"dumbbell seated box jump","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.","Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."],"src":"fedb","img":"fedb/Dumbbell_Seated_Box_Jump/0.jpg","img2":"fedb/Dumbbell_Seated_Box_Jump/1.jpg"},
{"id":"fe_c8a2e0b4","n":"dynamic back stretch","bp":"back","eq":"body weight","tg":"lats","sm":[],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"src":"fedb","img":"fedb/Dynamic_Back_Stretch/0.jpg","img2":"fedb/Dynamic_Back_Stretch/1.jpg"},
{"id":"fe_39e41e86","n":"ez-bar skullcrusher","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."],"src":"fedb","img":"fedb/EZ-Bar_Skullcrusher/0.jpg","img2":"fedb/EZ-Bar_Skullcrusher/1.jpg"},
{"id":"fe_3ffb0445","n":"elbow circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."],"src":"fedb","img":"fedb/Elbow_Circles/0.jpg","img2":"fedb/Elbow_Circles/1.jpg"},
{"id":"fe_a105e804","n":"elbows back","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."],"src":"fedb","img":"fedb/Elbows_Back/0.jpg","img2":"fedb/Elbows_Back/1.jpg"},
{"id":"fe_68227796","n":"elevated back lunge","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.","Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.","Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."],"src":"fedb","img":"fedb/Elevated_Back_Lunge/0.jpg","img2":"fedb/Elevated_Back_Lunge/1.jpg"},
{"id":"fe_0c159918","n":"elevated cable rows","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","traps"],"st":["Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.","Place it on the seat of the cable row machine.","Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Elevated_Cable_Rows/0.jpg","img2":"fedb/Elevated_Cable_Rows/1.jpg"},
{"id":"fe_593cfa37","n":"external rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","sm":[],"st":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.","Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"src":"fedb","img":"fedb/External_Rotation/0.jpg","img2":"fedb/External_Rotation/1.jpg"},
{"id":"fe_cbe20356","n":"external rotation with band","bp":"shoulders","eq":"band","tg":"delts","sm":[],"st":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"src":"fedb","img":"fedb/External_Rotation_with_Band/0.jpg","img2":"fedb/External_Rotation_with_Band/1.jpg"},
{"id":"fe_733d0bef","n":"face pull","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper back","sm":["upper back"],"st":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"src":"fedb","img":"fedb/Face_Pull/0.jpg","img2":"fedb/Face_Pull/1.jpg"},
{"id":"fe_ada8ee71","n":"fast skipping","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."],"src":"fedb","img":"fedb/Fast_Skipping/0.jpg","img2":"fedb/Fast_Skipping/1.jpg"},
{"id":"fe_81eff975","n":"floor press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."],"src":"fedb","img":"fedb/Floor_Press/0.jpg","img2":"fedb/Floor_Press/1.jpg"},
{"id":"fe_5424b31b","n":"foot-smr","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."],"src":"fedb","img":"fedb/Foot-SMR/0.jpg","img2":"fedb/Foot-SMR/1.jpg"},
{"id":"fe_e61c1367","n":"forward drag with press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"calves","sm":["calves","glutes","hamstrings","quadriceps","shoulders","triceps"],"st":["Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.","Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press."],"src":"fedb","img":"fedb/Forward_Drag_with_Press/0.jpg","img2":"fedb/Forward_Drag_with_Press/1.jpg"},
{"id":"fe_2ff5462a","n":"frog hops","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."],"src":"fedb","img":"fedb/Frog_Hops/0.jpg","img2":"fedb/Frog_Hops/1.jpg"},
{"id":"fe_8be2b06d","n":"frog sit-ups","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Frog_Sit-Ups/0.jpg","img2":"fedb/Frog_Sit-Ups/1.jpg"},
{"id":"fe_49c960d4","n":"front box jump","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","inner thighs","calves","quadriceps"],"st":["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."],"src":"fedb","img":"fedb/Front_Box_Jump/0.jpg","img2":"fedb/Front_Box_Jump/1.jpg"},
{"id":"fe_4395ed1f","n":"front cone hops (or hurdle hops)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."],"src":"fedb","img":"fedb/Front_Cone_Hops_or_hurdle_hops/0.jpg","img2":"fedb/Front_Cone_Hops_or_hurdle_hops/1.jpg"},
{"id":"fe_ae05bfdf","n":"front leg raises","bp":"upper legs","eq":"body weight","tg":"hamstrings","sm":[],"st":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"src":"fedb","img":"fedb/Front_Leg_Raises/0.jpg","img2":"fedb/Front_Leg_Raises/1.jpg"},
{"id":"fe_e1c2f111","n":"glute kickback","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"src":"fedb","img":"fedb/Glute_Kickback/0.jpg","img2":"fedb/Glute_Kickback/1.jpg"},
{"id":"fe_a88b5363","n":"good morning off pins","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"abdominals","sm":["abdominals","glutes","lower back"],"st":["Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position."],"src":"fedb","img":"fedb/Good_Morning_off_Pins/0.jpg","img2":"fedb/Good_Morning_off_Pins/1.jpg"},
{"id":"fe_af691cf5","n":"groin and back stretch","bp":"upper legs","eq":"body weight","tg":"adductors","sm":[],"st":["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head. This will be your starting position.","Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions."],"src":"fedb","img":"fedb/Groin_and_Back_Stretch/0.jpg","img2":"fedb/Groin_and_Back_Stretch/1.jpg"},
{"id":"fe_10a7b7ec","n":"groiners","bp":"upper legs","eq":"body weight","tg":"adductors","sm":[],"st":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"src":"fedb","img":"fedb/Groiners/0.jpg","img2":"fedb/Groiners/1.jpg"},
{"id":"fe_a3a2374b","n":"hamstring-smr","bp":"upper legs","eq":"roller","tg":"hamstrings","sm":[],"st":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"src":"fedb","img":"fedb/Hamstring-SMR/0.jpg","img2":"fedb/Hamstring-SMR/1.jpg"},
{"id":"fe_e5006c00","n":"hang clean","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"st":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"src":"fedb","img":"fedb/Hang_Clean/0.jpg","img2":"fedb/Hang_Clean/1.jpg"},
{"id":"fe_8aeb1069","n":"hang clean - below the knees","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"st":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.","At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"src":"fedb","img":"fedb/Hang_Clean_-_Below_the_Knees/0.jpg","img2":"fedb/Hang_Clean_-_Below_the_Knees/1.jpg"},
{"id":"fe_27a79037","n":"hang snatch","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"abdominals","sm":["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"st":["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control."],"src":"fedb","img":"fedb/Hang_Snatch/0.jpg","img2":"fedb/Hang_Snatch/1.jpg"},
{"id":"fe_754315f1","n":"hanging bar good morning","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"abdominals","sm":["abdominals","glutes","lower back"],"st":["Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.","Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.","Slowly lower the weight back to the starting position, where it is supported by the chains."],"src":"fedb","img":"fedb/Hanging_Bar_Good_Morning/0.jpg","img2":"fedb/Hanging_Bar_Good_Morning/1.jpg"},
{"id":"fe_6fe10ba8","n":"heaving snatch balance","bp":"upper legs","eq":"barbell","tg":"quads","mg":"abdominals","sm":["abdominals","forearms","glutes","hamstrings","shoulders","triceps"],"st":["This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.","Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.","Return to a standing position."],"src":"fedb","img":"fedb/Heaving_Snatch_Balance/0.jpg","img2":"fedb/Heaving_Snatch_Balance/1.jpg"},
{"id":"fe_977428f5","n":"heavy bag thrust","bp":"chest","eq":"body weight","tg":"pectorals","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.","Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.","Receive the bag as it swings back by reversing these steps."],"src":"fedb","img":"fedb/Heavy_Bag_Thrust/0.jpg","img2":"fedb/Heavy_Bag_Thrust/1.jpg"},
{"id":"fe_86c3bc53","n":"hip circles (prone)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"inner thighs","sm":["inner thighs"],"st":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"src":"fedb","img":"fedb/Hip_Circles_prone/0.jpg","img2":"fedb/Hip_Circles_prone/1.jpg"},
{"id":"fe_7f2f9279","n":"hip extension with bands","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"src":"fedb","img":"fedb/Hip_Extension_with_Bands/0.jpg","img2":"fedb/Hip_Extension_with_Bands/1.jpg"},
{"id":"fe_1156afc8","n":"hip flexion with band","bp":"upper legs","eq":"band","tg":"quads","sm":[],"st":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."],"src":"fedb","img":"fedb/Hip_Flexion_with_Band/0.jpg","img2":"fedb/Hip_Flexion_with_Band/1.jpg"},
{"id":"fe_193d396e","n":"hug knees to chest","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes"],"st":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."],"src":"fedb","img":"fedb/Hug_Knees_To_Chest/0.jpg","img2":"fedb/Hug_Knees_To_Chest/1.jpg"},
{"id":"fe_a78a55d1","n":"hurdle hops","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","inner thighs","calves"],"st":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."],"src":"fedb","img":"fedb/Hurdle_Hops/0.jpg","img2":"fedb/Hurdle_Hops/1.jpg"},
{"id":"fe_cfe25ffe","n":"it band and glute stretch","bp":"upper legs","eq":"band","tg":"abductors","sm":[],"st":["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side."],"src":"fedb","img":"fedb/IT_Band_and_Glute_Stretch/0.jpg","img2":"fedb/IT_Band_and_Glute_Stretch/1.jpg"},
{"id":"fe_50f4f201","n":"iliotibial tract-smr","bp":"upper legs","eq":"roller","tg":"abductors","sm":[],"st":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."],"src":"fedb","img":"fedb/Iliotibial_Tract-SMR/0.jpg","img2":"fedb/Iliotibial_Tract-SMR/1.jpg"},
{"id":"fe_326d844c","n":"incline bench pull","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","shoulders"],"st":["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.","Let the arms hang to your sides fully extended as they point to the floor.","Turn the wrists until your hands have a pronated (palms down) grip.","Now flare the elbows out. This will be your starting position.","As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter \"T\" at the top of the movement. Hold the contraction at the top for a second.","Slowly go back down to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Incline_Bench_Pull/0.jpg","img2":"fedb/Incline_Bench_Pull/1.jpg"},
{"id":"fe_6019f4aa","n":"intermediate groin stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","sm":[],"st":["Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.","Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side."],"src":"fedb","img":"fedb/Intermediate_Groin_Stretch/0.jpg","img2":"fedb/Intermediate_Groin_Stretch/1.jpg"},
{"id":"fe_3e63999f","n":"internal rotation with band","bp":"shoulders","eq":"band","tg":"delts","sm":[],"st":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.","Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"src":"fedb","img":"fedb/Internal_Rotation_with_Band/0.jpg","img2":"fedb/Internal_Rotation_with_Band/1.jpg"},
{"id":"fe_b281bc41","n":"isometric neck exercise - front and back","bp":"neck","eq":"body weight","tg":"levator scapulae","sm":[],"st":["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."],"src":"fedb","img":"fedb/Isometric_Neck_Exercise_-_Front_And_Back/0.jpg","img2":"fedb/Isometric_Neck_Exercise_-_Front_And_Back/1.jpg"},
{"id":"fe_415256f8","n":"isometric neck exercise - sides","bp":"neck","eq":"body weight","tg":"levator scapulae","sm":[],"st":["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."],"src":"fedb","img":"fedb/Isometric_Neck_Exercise_-_Sides/0.jpg","img2":"fedb/Isometric_Neck_Exercise_-_Sides/1.jpg"},
{"id":"fe_03d624a1","n":"jerk balance","bp":"shoulders","eq":"barbell","tg":"delts","mg":"glutes","sm":["glutes","hamstrings","quadriceps","triceps"],"st":["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead."],"src":"fedb","img":"fedb/Jerk_Balance/0.jpg","img2":"fedb/Jerk_Balance/1.jpg"},
{"id":"fe_8b285fa6","n":"keg load","bp":"back","eq":"weighted","tg":"spine","mg":"abdominals","sm":["abdominals","biceps","calves","forearms","glutes","hamstrings","upper back","quadriceps","shoulders","traps"],"st":["To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.","Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.","The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.","Return to the starting position to retrieve the next keg, and repeat until the event is completed."],"src":"fedb","img":"fedb/Keg_Load/0.jpg","img2":"fedb/Keg_Load/1.jpg"},
{"id":"fe_33d91e6d","n":"kettlebell dead clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back","quadriceps","traps"],"st":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."],"src":"fedb","img":"fedb/Kettlebell_Dead_Clean/0.jpg","img2":"fedb/Kettlebell_Dead_Clean/1.jpg"},
{"id":"fe_c52488b3","n":"kettlebell halo","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"traps","sm":["traps","upper back","abdominals","triceps"],"st":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."],"src":"fedb"},
{"id":"fe_d094d96f","n":"kettlebell halo with overhead extension","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","traps","upper back","abdominals"],"st":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.","From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.","Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.","Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.","Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises."],"src":"fedb"},
{"id":"fe_d58993f3","n":"kettlebell one-legged deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"src":"fedb","img":"fedb/Kettlebell_One-Legged_Deadlift/0.jpg","img2":"fedb/Kettlebell_One-Legged_Deadlift/1.jpg"},
{"id":"fe_050fc8e8","n":"kettlebell overhead triceps extension","bp":"upper arms","eq":"kettlebell","tg":"triceps","mg":"shoulders","sm":["shoulders","abdominals"],"st":["Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.","Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.","Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.","Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.","Keep your ribcage down and avoid arching your lower back as you extend."],"src":"fedb"},
{"id":"fe_8e29091d","n":"kettlebell pass between the legs","bp":"waist","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."],"src":"fedb","img":"fedb/Kettlebell_Pass_Between_The_Legs/0.jpg","img2":"fedb/Kettlebell_Pass_Between_The_Legs/1.jpg"},
{"id":"fe_bf84b238","n":"kettlebell pirate ships","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"abdominals","sm":["abdominals"],"st":["With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.","Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.","Repeat for the desired amount of repetitions."],"src":"fedb","img":"fedb/Kettlebell_Pirate_Ships/0.jpg","img2":"fedb/Kettlebell_Pirate_Ships/1.jpg"},
{"id":"fe_9cd4d40e","n":"knee across the body","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back"],"st":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"src":"fedb","img":"fedb/Knee_Across_The_Body/0.jpg","img2":"fedb/Knee_Across_The_Body/1.jpg"},
{"id":"fe_c0bd86b2","n":"knee tuck jump","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","inner thighs","calves","quadriceps"],"st":["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."],"src":"fedb","img":"fedb/Knee_Tuck_Jump/0.jpg","img2":"fedb/Knee_Tuck_Jump/1.jpg"},
{"id":"fe_3e751df2","n":"kneeling cable crunch with alternating oblique twists","bp":"waist","eq":"cable","tg":"abs","sm":[],"st":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you're halfway down, at which time you'll begin rotating one of your elbows to the opposite knee.","Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same movement as before, but alternate the other elbow to the opposite knee.","Continue this series of movements to failure."],"src":"fedb","img":"fedb/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg","img2":"fedb/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg"},
{"id":"fe_2620801f","n":"kneeling forearm stretch","bp":"lower arms","eq":"body weight","tg":"forearms","sm":[],"st":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"src":"fedb","img":"fedb/Kneeling_Forearm_Stretch/0.jpg","img2":"fedb/Kneeling_Forearm_Stretch/1.jpg"},
{"id":"fe_ca6cb927","n":"kneeling hip flexor","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"src":"fedb","img":"fedb/Kneeling_Hip_Flexor/0.jpg","img2":"fedb/Kneeling_Hip_Flexor/1.jpg"},
{"id":"fe_22aff575","n":"kneeling single-arm high pulley row","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back"],"st":["Attach a single handle to a high pulley and make your weight selection.","Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.","Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.","After a brief pause, return to the starting position."],"src":"fedb","img":"fedb/Kneeling_Single-Arm_High_Pulley_Row/0.jpg","img2":"fedb/Kneeling_Single-Arm_High_Pulley_Row/1.jpg"},
{"id":"fe_8778fec6","n":"landmine linear jammer","bp":"shoulders","eq":"barbell","tg":"delts","mg":"abdominals","sm":["abdominals","calves","chest","hamstrings","quadriceps","triceps"],"st":["Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.","Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.","In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.","Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.","Return to the starting position."],"src":"fedb","img":"fedb/Landmine_Linear_Jammer/0.jpg","img2":"fedb/Landmine_Linear_Jammer/1.jpg"},
{"id":"fe_28fd27fa","n":"lateral bound","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","calves","hamstrings","quadriceps"],"st":["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."],"src":"fedb","img":"fedb/Lateral_Bound/0.jpg","img2":"fedb/Lateral_Bound/1.jpg"},
{"id":"fe_40c0944b","n":"lateral box jump","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","calves","hamstrings","quadriceps"],"st":["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."],"src":"fedb","img":"fedb/Lateral_Box_Jump/0.jpg","img2":"fedb/Lateral_Box_Jump/1.jpg"},
{"id":"fe_468f06ae","n":"lateral cone hops","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","calves","hamstrings","quadriceps"],"st":["Position a number of cones in a row several feet apart.","Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."],"src":"fedb","img":"fedb/Lateral_Cone_Hops/0.jpg","img2":"fedb/Lateral_Cone_Hops/1.jpg"},
{"id":"fe_550812ad","n":"latissimus dorsi-smr","bp":"back","eq":"roller","tg":"lats","sm":[],"st":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."],"src":"fedb","img":"fedb/Latissimus_Dorsi-SMR/0.jpg","img2":"fedb/Latissimus_Dorsi-SMR/1.jpg"},
{"id":"fe_25d7ca40","n":"leg-over floor press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions."],"src":"fedb","img":"fedb/Leg-Over_Floor_Press/0.jpg","img2":"fedb/Leg-Over_Floor_Press/1.jpg"},
{"id":"fe_ecf0a29a","n":"leg lift","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.","With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.","Slowly bring the raised leg back to the floor as you breathe in.","Repeat for the recommended amount of repetitions.","Repeat the movement with the opposite leg."],"src":"fedb","img":"fedb/Leg_Lift/0.jpg","img2":"fedb/Leg_Lift/1.jpg"},
{"id":"fe_f953df0f","n":"leg pull-in","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Leg_Pull-In/0.jpg","img2":"fedb/Leg_Pull-In/1.jpg"},
{"id":"fe_f9d54bcc","n":"leverage iso row","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","upper back"],"st":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"src":"fedb","img":"fedb/Leverage_Iso_Row/0.jpg","img2":"fedb/Leverage_Iso_Row/1.jpg"},
{"id":"fe_c150419e","n":"linear depth jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.","To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."],"src":"fedb","img":"fedb/Linear_Depth_Jump/0.jpg","img2":"fedb/Linear_Depth_Jump/1.jpg"},
{"id":"fe_e29aa012","n":"log lift","bp":"shoulders","eq":"weighted","tg":"delts","mg":"abdominals","sm":["abdominals","chest","glutes","hamstrings","lower back","upper back","quadriceps","traps","triceps"],"st":["Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.","Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.","Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground."],"src":"fedb","img":"fedb/Log_Lift/0.jpg","img2":"fedb/Log_Lift/1.jpg"},
{"id":"fe_5c1dc150","n":"looking at ceiling","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."],"src":"fedb","img":"fedb/Looking_At_Ceiling/0.jpg","img2":"fedb/Looking_At_Ceiling/1.jpg"},
{"id":"fe_0d8cd7c1","n":"low pulley row to neck","bp":"shoulders","eq":"cable","tg":"delts","mg":"biceps","sm":["biceps","upper back","traps"],"st":["Sit on a low pulley row machine with a rope attachment.","Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.","While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.","After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Low_Pulley_Row_To_Neck/0.jpg","img2":"fedb/Low_Pulley_Row_To_Neck/1.jpg"},
{"id":"fe_6736dea8","n":"lower back-smr","bp":"back","eq":"roller","tg":"spine","sm":[],"st":["In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.","Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side."],"src":"fedb","img":"fedb/Lower_Back-SMR/0.jpg","img2":"fedb/Lower_Back-SMR/1.jpg"},
{"id":"fe_c32a75f2","n":"lying bent leg groin","bp":"upper legs","eq":"body weight","tg":"adductors","sm":[],"st":["Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"src":"fedb","img":"fedb/Lying_Bent_Leg_Groin/0.jpg","img2":"fedb/Lying_Bent_Leg_Groin/1.jpg"},
{"id":"fe_9e62bc69","n":"lying close-grip bar curl on high pulley","bp":"upper arms","eq":"cable","tg":"biceps","sm":[],"st":["Place a flat bench in front of a high pulley or lat pulldown machine.","Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.","Lie on your back with your head over the end of the bench.","Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.","As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.","Return to starting position slowly.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg","img2":"fedb/Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg"},
{"id":"fe_f6d74824","n":"lying crossover","bp":"upper legs","eq":"body weight","tg":"abductors","sm":[],"st":["Lie on your back with your legs extended.","Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side."],"src":"fedb","img":"fedb/Lying_Crossover/0.jpg","img2":"fedb/Lying_Crossover/1.jpg"},
{"id":"fe_4dd9522f","n":"lying face down plate neck resistance","bp":"neck","eq":"weighted","tg":"levator scapulae","sm":[],"st":["Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.","While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Lying_Face_Down_Plate_Neck_Resistance/0.jpg","img2":"fedb/Lying_Face_Down_Plate_Neck_Resistance/1.jpg"},
{"id":"fe_6888c3d9","n":"lying glute","bp":"upper legs","eq":"body weight","tg":"glutes","sm":[],"st":["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"src":"fedb","img":"fedb/Lying_Glute/0.jpg","img2":"fedb/Lying_Glute/1.jpg"},
{"id":"fe_a91f74c4","n":"lying hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete."],"src":"fedb","img":"fedb/Lying_Hamstring/0.jpg","img2":"fedb/Lying_Hamstring/1.jpg"},
{"id":"fe_f5f2821b","n":"lying high bench barbell curl","bp":"upper arms","eq":"barbell","tg":"biceps","sm":[],"st":["Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.","While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.","As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Lying_High_Bench_Barbell_Curl/0.jpg","img2":"fedb/Lying_High_Bench_Barbell_Curl/1.jpg"},
{"id":"fe_9501b3a9","n":"lying prone quadriceps","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.","Attempt to extend your knee while your partner prevents any actual movement.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."],"src":"fedb","img":"fedb/Lying_Prone_Quadriceps/0.jpg","img2":"fedb/Lying_Prone_Quadriceps/1.jpg"},
{"id":"fe_f1d51a49","n":"medicine ball full twist","bp":"waist","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders"],"st":["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."],"src":"fedb","img":"fedb/Medicine_Ball_Full_Twist/0.jpg","img2":"fedb/Medicine_Ball_Full_Twist/1.jpg"},
{"id":"fe_9da0ddb7","n":"middle back shrug","bp":"back","eq":"dumbbell","tg":"upper back","sm":[],"st":["Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.","As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.","As you inhale go back to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Middle_Back_Shrug/0.jpg","img2":"fedb/Middle_Back_Shrug/1.jpg"},
{"id":"fe_c804d7d5","n":"middle back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"abdominals","sm":["abdominals","lats","lower back"],"st":["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side."],"src":"fedb","img":"fedb/Middle_Back_Stretch/0.jpg","img2":"fedb/Middle_Back_Stretch/1.jpg"},
{"id":"fe_b8f4c30d","n":"mixed grip chin","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.","Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.","After a second contraction at the top, start to slowly come down as you inhale.","Repeat for the recommended amount of repetitions.","On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left."],"src":"fedb","img":"fedb/Mixed_Grip_Chin/0.jpg","img2":"fedb/Mixed_Grip_Chin/1.jpg"},
{"id":"fe_eb2bbf53","n":"muscle snatch","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps","shoulders","triceps"],"st":["Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.","Continue raising the bar to the overhead position, without rebending the knees."],"src":"fedb","img":"fedb/Muscle_Snatch/0.jpg","img2":"fedb/Muscle_Snatch/1.jpg"},
{"id":"fe_dee34fb2","n":"narrow stance hack squats","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position.","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Narrow_Stance_Hack_Squats/0.jpg","img2":"fedb/Narrow_Stance_Hack_Squats/1.jpg"},
{"id":"fe_ab72d637","n":"narrow stance leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"src":"fedb","img":"fedb/Narrow_Stance_Leg_Press/0.jpg","img2":"fedb/Narrow_Stance_Leg_Press/1.jpg"},
{"id":"fe_fddd840b","n":"neck-smr","bp":"neck","eq":"roller","tg":"levator scapulae","sm":[],"st":["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."],"src":"fedb","img":"fedb/Neck-SMR/0.jpg","img2":"fedb/Neck-SMR/1.jpg"},
{"id":"fe_b808300c","n":"neck press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"src":"fedb","img":"fedb/Neck_Press/0.jpg","img2":"fedb/Neck_Press/1.jpg"},
{"id":"fe_ca195b1e","n":"on-your-back quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Lie on a flat bench or step, and hang one leg and arm over the side.","Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.","Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you're holding up toward the ceiling.","Switch sides."],"src":"fedb","img":"fedb/On-Your-Back_Quad_Stretch/0.jpg","img2":"fedb/On-Your-Back_Quad_Stretch/1.jpg"},
{"id":"fe_8d841121","n":"one-arm high-pulley cable side bends","bp":"waist","eq":"cable","tg":"abs","sm":[],"st":["Connect a standard handle to a tower. Move cable to highest pulley position.","Stand with side to cable. With one hand, reach up and grab handle with underhand grip.","Pull down cable until elbow touches your side and the handle is by your shoulder.","Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","Keep arm in static position. Contract oblique to bring the weight down in a side crunch.","Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"src":"fedb","img":"fedb/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg","img2":"fedb/One-Arm_High-Pulley_Cable_Side_Bends/1.jpg"},
{"id":"fe_1f8e8468","n":"one-arm kettlebell clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","shoulders","traps"],"st":["Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Return the weight to the starting position."],"src":"fedb","img":"fedb/One-Arm_Kettlebell_Clean/0.jpg","img2":"fedb/One-Arm_Kettlebell_Clean/1.jpg"},
{"id":"fe_e881770a","n":"one-arm long bar row","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.","Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.","Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"src":"fedb","img":"fedb/One-Arm_Long_Bar_Row/0.jpg","img2":"fedb/One-Arm_Long_Bar_Row/1.jpg"},
{"id":"fe_4ec719fd","n":"one-arm overhead kettlebell squats","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders"],"st":["Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."],"src":"fedb","img":"fedb/One-Arm_Overhead_Kettlebell_Squats/0.jpg","img2":"fedb/One-Arm_Overhead_Kettlebell_Squats/1.jpg"},
{"id":"fe_1d24b920","n":"one-legged cable kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."],"src":"fedb","img":"fedb/One-Legged_Cable_Kickback/0.jpg","img2":"fedb/One-Legged_Cable_Kickback/1.jpg"},
{"id":"fe_8a1410b5","n":"one half locust","bp":"upper legs","eq":"body weight","tg":"quads","mg":"abdominals","sm":["abdominals","biceps","chest"],"st":["Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time."],"src":"fedb","img":"fedb/One_Half_Locust/0.jpg","img2":"fedb/One_Half_Locust/1.jpg"},
{"id":"fe_146a662d","n":"one handed hang","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps"],"st":["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."],"src":"fedb","img":"fedb/One_Handed_Hang/0.jpg","img2":"fedb/One_Handed_Hang/1.jpg"},
{"id":"fe_84579dba","n":"one knee to chest","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."],"src":"fedb","img":"fedb/One_Knee_To_Chest/0.jpg","img2":"fedb/One_Knee_To_Chest/1.jpg"},
{"id":"fe_4ed63785","n":"open palm kettlebell clean","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps","shoulders"],"st":["Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat."],"src":"fedb","img":"fedb/Open_Palm_Kettlebell_Clean/0.jpg","img2":"fedb/Open_Palm_Kettlebell_Clean/1.jpg"},
{"id":"fe_6577b791","n":"overhead lat","bp":"back","eq":"body weight","tg":"lats","mg":"triceps","sm":["triceps"],"st":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."],"src":"fedb","img":"fedb/Overhead_Lat/0.jpg","img2":"fedb/Overhead_Lat/1.jpg"},
{"id":"fe_2360a42d","n":"overhead slam","bp":"back","eq":"medicine ball","tg":"lats","sm":[],"st":["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."],"src":"fedb","img":"fedb/Overhead_Slam/0.jpg","img2":"fedb/Overhead_Slam/1.jpg"},
{"id":"fe_beb68c59","n":"pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"chest","sm":["chest","shoulders","triceps"],"st":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"src":"fedb","img":"fedb/Pallof_Press/0.jpg","img2":"fedb/Pallof_Press/1.jpg"},
{"id":"fe_449c5665","n":"peroneals-smr","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"src":"fedb","img":"fedb/Peroneals-SMR/0.jpg","img2":"fedb/Peroneals-SMR/1.jpg"},
{"id":"fe_fe0e3df2","n":"physioball hip bridge","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."],"src":"fedb","img":"fedb/Physioball_Hip_Bridge/0.jpg","img2":"fedb/Physioball_Hip_Bridge/1.jpg"},
{"id":"fe_29a27d0d","n":"piriformis-smr","bp":"upper legs","eq":"roller","tg":"glutes","sm":[],"st":["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."],"src":"fedb","img":"fedb/Piriformis-SMR/0.jpg","img2":"fedb/Piriformis-SMR/1.jpg"},
{"id":"fe_445fb6f4","n":"plank","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"src":"fedb","img":"fedb/Plank/0.jpg","img2":"fedb/Plank/1.jpg"},
{"id":"fe_86b20510","n":"plate pinch","bp":"lower arms","eq":"weighted","tg":"forearms","sm":[],"st":["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.","Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.","Repeat for the recommended amount of sets prescribed in your program.","Switch arms and repeat the movements."],"src":"fedb","img":"fedb/Plate_Pinch/0.jpg","img2":"fedb/Plate_Pinch/1.jpg"},
{"id":"fe_75002120","n":"plate twist","bp":"waist","eq":"weighted","tg":"abs","sm":[],"st":["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.","Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.","Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Plate_Twist/0.jpg","img2":"fedb/Plate_Twist/1.jpg"},
{"id":"fe_90c145ad","n":"platform hamstring slides","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.","Begin the movement by flexing the knee, keeping your other leg straight.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."],"src":"fedb","img":"fedb/Platform_Hamstring_Slides/0.jpg","img2":"fedb/Platform_Hamstring_Slides/1.jpg"},
{"id":"fe_3eca1437","n":"plie dumbbell squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"abdominals","sm":["abdominals","calves","glutes","hamstrings"],"st":["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.","Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Plie_Dumbbell_Squat/0.jpg","img2":"fedb/Plie_Dumbbell_Squat/1.jpg"},
{"id":"fe_6ee93643","n":"power clean from blocks","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps"],"st":["With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.","In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes."],"src":"fedb","img":"fedb/Power_Clean_from_Blocks/0.jpg","img2":"fedb/Power_Clean_from_Blocks/1.jpg"},
{"id":"fe_bd3da88e","n":"power jerk","bp":"upper legs","eq":"barbell","tg":"quads","mg":"abdominals","sm":["abdominals","calves","glutes","hamstrings","shoulders","triceps"],"st":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.","Receive the bar with the arms locked out overhead.","Return to a standing position."],"src":"fedb","img":"fedb/Power_Jerk/0.jpg","img2":"fedb/Power_Jerk/1.jpg"},
{"id":"fe_6ff053b3","n":"power partials","bp":"shoulders","eq":"dumbbell","tg":"delts","sm":[],"st":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.","Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.","Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Power_Partials/0.jpg","img2":"fedb/Power_Partials/1.jpg"},
{"id":"fe_8c91cfbf","n":"power snatch","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back","quadriceps","shoulders","traps","triceps"],"st":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."],"src":"fedb","img":"fedb/Power_Snatch/0.jpg","img2":"fedb/Power_Snatch/1.jpg"},
{"id":"fe_f222e2b6","n":"power stairs","bp":"upper legs","eq":"weighted","tg":"hamstrings","mg":"inner thighs","sm":["inner thighs","calves","glutes","lower back","quadriceps","shoulders","traps"],"st":["In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.","Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.","As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18\" high. You can use your legs to help push the weight onto the stair.","Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible."],"src":"fedb","img":"fedb/Power_Stairs/0.jpg","img2":"fedb/Power_Stairs/1.jpg"},
{"id":"fe_ffcee5f3","n":"prone manual hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","sm":[],"st":["You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.","To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.","Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction."],"src":"fedb","img":"fedb/Prone_Manual_Hamstring/0.jpg","img2":"fedb/Prone_Manual_Hamstring/1.jpg"},
{"id":"fe_55be5ac8","n":"prowler sprint","bp":"cardio","eq":"body weight","tg":"cardiovascular system","sm":[],"st":["Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.","You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.","With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance."],"src":"fedb","img":"fedb/Prowler_Sprint/0.jpg","img2":"fedb/Prowler_Sprint/1.jpg"},
{"id":"fe_98668e49","n":"push-ups with feet on an exercise ball","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of an exercise ball. This will allow your body to be elevated.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"src":"fedb","img":"fedb/Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg","img2":"fedb/Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg"},
{"id":"fe_347b0bdb","n":"pyramid","bp":"back","eq":"stability ball","tg":"spine","mg":"shoulders","sm":["shoulders"],"st":["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders."],"src":"fedb","img":"fedb/Pyramid/0.jpg","img2":"fedb/Pyramid/1.jpg"},
{"id":"fe_84427ae0","n":"quadriceps-smr","bp":"upper legs","eq":"roller","tg":"quads","sm":[],"st":["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."],"src":"fedb","img":"fedb/Quadriceps-SMR/0.jpg","img2":"fedb/Quadriceps-SMR/1.jpg"},
{"id":"fe_67660445","n":"quick leap","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["You will need a box for this exerise.","Begin facing the box standing 1-2 feet from its edge.","By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing."],"src":"fedb","img":"fedb/Quick_Leap/0.jpg","img2":"fedb/Quick_Leap/1.jpg"},
{"id":"fe_963a25f6","n":"rack delivery","bp":"shoulders","eq":"barbell","tg":"delts","mg":"forearms","sm":["forearms","traps"],"st":["This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.","Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.","It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further."],"src":"fedb","img":"fedb/Rack_Delivery/0.jpg","img2":"fedb/Rack_Delivery/1.jpg"},
{"id":"fe_632a9a51","n":"rear leg raises","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."],"src":"fedb","img":"fedb/Rear_Leg_Raises/0.jpg","img2":"fedb/Rear_Leg_Raises/1.jpg"},
{"id":"fe_d83d1357","n":"recumbent bike","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","sm":[],"st":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running."],"src":"fedb","img":"fedb/Recumbent_Bike/0.jpg","img2":"fedb/Recumbent_Bike/1.jpg"},
{"id":"fe_be29439e","n":"return push from stance","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"chest","sm":["chest","triceps"],"st":["You will need a partner for this drill.","Begin in an athletic 2 or 3 point stance.","At the signal, move into a position to receive the pass from your partner.","Catch the medicine ball with both hands and immediately throw it back to your partner.","You can modify this drill by running different routes."],"src":"fedb","img":"fedb/Return_Push_from_Stance/0.jpg","img2":"fedb/Return_Push_from_Stance/1.jpg"},
{"id":"fe_69cdff41","n":"reverse band deadlift","bp":"back","eq":"barbell","tg":"spine","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings","quadriceps"],"st":["Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"src":"fedb","img":"fedb/Reverse_Band_Deadlift/0.jpg","img2":"fedb/Reverse_Band_Deadlift/1.jpg"},
{"id":"fe_cbe3f42f","n":"reverse band power squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"inner thighs","sm":["inner thighs","calves","glutes","hamstrings","lower back"],"st":["Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.","Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"src":"fedb","img":"fedb/Reverse_Band_Power_Squat/0.jpg","img2":"fedb/Reverse_Band_Power_Squat/1.jpg"},
{"id":"fe_b27a1bdb","n":"reverse plate curls","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o'clock position.","Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.","Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.","Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Reverse_Plate_Curls/0.jpg","img2":"fedb/Reverse_Plate_Curls/1.jpg"},
{"id":"fe_e490e8fd","n":"reverse triceps bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"src":"fedb","img":"fedb/Reverse_Triceps_Bench_Press/0.jpg","img2":"fedb/Reverse_Triceps_Bench_Press/1.jpg"},
{"id":"fe_0aa41055","n":"rhomboids-smr","bp":"back","eq":"roller","tg":"upper back","mg":"traps","sm":["traps"],"st":["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."],"src":"fedb","img":"fedb/Rhomboids-SMR/0.jpg","img2":"fedb/Rhomboids-SMR/1.jpg"},
{"id":"fe_33d32439","n":"rickshaw carry","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"abdominals","sm":["abdominals","calves","glutes","hamstrings","lower back","quadriceps","traps"],"st":["Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.","Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point."],"src":"fedb","img":"fedb/Rickshaw_Carry/0.jpg","img2":"fedb/Rickshaw_Carry/1.jpg"},
{"id":"fe_5e6a939d","n":"rickshaw deadlift","bp":"upper legs","eq":"weighted","tg":"quads","mg":"forearms","sm":["forearms","glutes","hamstrings","lower back","traps"],"st":["Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the ground."],"src":"fedb","img":"fedb/Rickshaw_Deadlift/0.jpg","img2":"fedb/Rickshaw_Deadlift/1.jpg"},
{"id":"fe_192b88dd","n":"rocket jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs."],"src":"fedb","img":"fedb/Rocket_Jump/0.jpg","img2":"fedb/Rocket_Jump/1.jpg"},
{"id":"fe_7463199e","n":"romanian deadlift from deficit","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"forearms","sm":["forearms","glutes","lower back","traps"],"st":["Begin standing while holding a bar at arm's length in front of you. You can stand on a raised platform to increase the range of motion.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.","Reverse the motion to return to the starting position."],"src":"fedb","img":"fedb/Romanian_Deadlift_from_Deficit/0.jpg","img2":"fedb/Romanian_Deadlift_from_Deficit/1.jpg"},
{"id":"fe_6201158d","n":"round the world shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest"],"st":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further."],"src":"fedb","img":"fedb/Round_The_World_Shoulder_Stretch/0.jpg","img2":"fedb/Round_The_World_Shoulder_Stretch/1.jpg"},
{"id":"fe_4d705453","n":"rowing, stationary","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","sm":[],"st":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"src":"fedb","img":"fedb/Rowing_Stationary/0.jpg","img2":"fedb/Rowing_Stationary/1.jpg"},
{"id":"fe_d9630c6c","n":"sandbag load","bp":"upper legs","eq":"weighted","tg":"quads","mg":"abdominals","sm":["abdominals","biceps","calves","forearms","glutes","hamstrings","lower back","upper back","shoulders","traps"],"st":["To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.","Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.","Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn't fall off.","Return to the starting position to retrieve the next sandbag, and repeat until the event is completed."],"src":"fedb","img":"fedb/Sandbag_Load/0.jpg","img2":"fedb/Sandbag_Load/1.jpg"},
{"id":"fe_95b60a54","n":"scissor kick","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Scissor_Kick/0.jpg","img2":"fedb/Scissor_Kick/1.jpg"},
{"id":"fe_32604a3c","n":"seated band hamstring curl","bp":"upper legs","eq":"band","tg":"hamstrings","sm":[],"st":["Secure a band close to the ground and place a bench a couple feet away from it.","Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.","Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.","Pause at the completion of the movement, and then slowly return to the starting position."],"src":"fedb","img":"fedb/Seated_Band_Hamstring_Curl/0.jpg","img2":"fedb/Seated_Band_Hamstring_Curl/1.jpg"},
{"id":"fe_d43cb9e4","n":"seated biceps","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching."],"src":"fedb","img":"fedb/Seated_Biceps/0.jpg","img2":"fedb/Seated_Biceps/1.jpg"},
{"id":"fe_0800acbf","n":"seated floor hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"src":"fedb","img":"fedb/Seated_Floor_Hamstring_Stretch/0.jpg","img2":"fedb/Seated_Floor_Hamstring_Stretch/1.jpg"},
{"id":"fe_1eb79787","n":"seated front deltoid","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest"],"st":["Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds."],"src":"fedb","img":"fedb/Seated_Front_Deltoid/0.jpg","img2":"fedb/Seated_Front_Deltoid/1.jpg"},
{"id":"fe_39a52d65","n":"seated hamstring","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"src":"fedb","img":"fedb/Seated_Hamstring/0.jpg","img2":"fedb/Seated_Hamstring/1.jpg"},
{"id":"fe_a9d5426f","n":"seated head harness neck resistance","bp":"neck","eq":"weighted","tg":"levator scapulae","sm":[],"st":["Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.","Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.","Now place both hands on top of your knees. This is the starting position.","Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.","While exhaling, bring your neck back to the starting position.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Seated_Head_Harness_Neck_Resistance/0.jpg","img2":"fedb/Seated_Head_Harness_Neck_Resistance/1.jpg"},
{"id":"fe_867c1638","n":"seated leg tucks","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Seated_Leg_Tucks/0.jpg","img2":"fedb/Seated_Leg_Tucks/1.jpg"},
{"id":"fe_cad94732","n":"seated overhead stretch","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."],"src":"fedb","img":"fedb/Seated_Overhead_Stretch/0.jpg","img2":"fedb/Seated_Overhead_Stretch/1.jpg"},
{"id":"fe_c2eeb1a6","n":"seated palm-up barbell wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","sm":[],"st":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."],"src":"fedb","img":"fedb/Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg","img2":"fedb/Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg"},
{"id":"fe_3d19177e","n":"seated two-arm palms-up low-pulley wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","sm":[],"st":["Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.","Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.","Now hold the handle with both hands, palms up, using a shoulder-width grip.","Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.","Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.","Lower the bar as far as possible, while inhaling and keeping a tight grip.","Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.","After a second contraction at the top go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg","img2":"fedb/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg"},
{"id":"fe_0efcbebf","n":"see-saw press (alternating side press)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"abdominals","sm":["abdominals","triceps"],"st":["Grab a dumbbell with each hand and stand up erect.","Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.","Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.","Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/See-Saw_Press_Alternating_Side_Press/0.jpg","img2":"fedb/See-Saw_Press_Alternating_Side_Press/1.jpg"},
{"id":"fe_46da7cae","n":"shotgun row","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back"],"st":["Attach a single handle to a low cable.","After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.","Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.","After a brief pause, return to the starting position."],"src":"fedb","img":"fedb/Shotgun_Row/0.jpg","img2":"fedb/Shotgun_Row/1.jpg"},
{"id":"fe_6c40b890","n":"shoulder circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"traps","sm":["traps"],"st":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"src":"fedb","img":"fedb/Shoulder_Circles/0.jpg","img2":"fedb/Shoulder_Circles/1.jpg"},
{"id":"fe_a6c217ae","n":"shoulder raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"lats","sm":["lats"],"st":["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."],"src":"fedb","img":"fedb/Shoulder_Raise/0.jpg","img2":"fedb/Shoulder_Raise/1.jpg"},
{"id":"fe_480f1c55","n":"shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","sm":[],"st":["Reach your left arm across your body and hold it straight."],"src":"fedb","img":"fedb/Shoulder_Stretch/0.jpg","img2":"fedb/Shoulder_Stretch/1.jpg"},
{"id":"fe_727db046","n":"side hop-sprint","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."],"src":"fedb","img":"fedb/Side_Hop-Sprint/0.jpg","img2":"fedb/Side_Hop-Sprint/1.jpg"},
{"id":"fe_739fb414","n":"side lying groin stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings"],"st":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."],"src":"fedb","img":"fedb/Side_Lying_Groin_Stretch/0.jpg","img2":"fedb/Side_Lying_Groin_Stretch/1.jpg"},
{"id":"fe_80573e7a","n":"side standing long jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."],"src":"fedb","img":"fedb/Side_Standing_Long_Jump/0.jpg","img2":"fedb/Side_Standing_Long_Jump/1.jpg"},
{"id":"fe_948050cb","n":"side to side box shuffle","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."],"src":"fedb","img":"fedb/Side_to_Side_Box_Shuffle/0.jpg","img2":"fedb/Side_to_Side_Box_Shuffle/1.jpg"},
{"id":"fe_36ca8fed","n":"single-arm cable crossover","bp":"chest","eq":"cable","tg":"pectorals","sm":[],"st":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.","Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.","Return your arm back to the starting position by pulling your hand back to the midline of the body.","Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions."],"src":"fedb","img":"fedb/Single-Arm_Cable_Crossover/0.jpg","img2":"fedb/Single-Arm_Cable_Crossover/1.jpg"},
{"id":"fe_09a6a4b7","n":"single-arm linear jammer","bp":"shoulders","eq":"barbell","tg":"delts","mg":"chest","sm":["chest","triceps"],"st":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.","Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.","Return to the starting position."],"src":"fedb","img":"fedb/Single-Arm_Linear_Jammer/0.jpg","img2":"fedb/Single-Arm_Linear_Jammer/1.jpg"},
{"id":"fe_ac720d70","n":"single-leg high box squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Position a box in a rack. Secure a band or rope in place above the box.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance",". Continue stepping up and down on the same leg before switching to the opposite side."],"src":"fedb","img":"fedb/Single-Leg_High_Box_Squat/0.jpg","img2":"fedb/Single-Leg_High_Box_Squat/1.jpg"},
{"id":"fe_6b0b21e0","n":"single-leg hop progression","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.","Hop forward, jumping and landing with the same leg over the cone.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."],"src":"fedb","img":"fedb/Single-Leg_Hop_Progression/0.jpg","img2":"fedb/Single-Leg_Hop_Progression/1.jpg"},
{"id":"fe_2398dba8","n":"single-leg stride jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the same position that you started, using your inside leg to decelerate the impact."],"src":"fedb","img":"fedb/Single-Leg_Stride_Jump/0.jpg","img2":"fedb/Single-Leg_Stride_Jump/1.jpg"},
{"id":"fe_497ddd39","n":"single dumbbell raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"forearms","sm":["forearms","traps"],"st":["With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.","Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.","Return to the starting position and repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Single_Dumbbell_Raise/0.jpg","img2":"fedb/Single_Dumbbell_Raise/1.jpg"},
{"id":"fe_0edd97fa","n":"single leg push-off","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."],"src":"fedb","img":"fedb/Single_Leg_Push-off/0.jpg","img2":"fedb/Single_Leg_Push-off/1.jpg"},
{"id":"fe_b21c57e5","n":"sit squats","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."],"src":"fedb","img":"fedb/Sit_Squats/0.jpg","img2":"fedb/Sit_Squats/1.jpg"},
{"id":"fe_5679dadc","n":"skating","bp":"cardio","eq":"body weight","tg":"cardiovascular system","sm":[],"st":["Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.","You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking."],"src":"fedb","img":"fedb/Skating/0.jpg","img2":"fedb/Skating/1.jpg"},
{"id":"fe_fc282087","n":"sled drag - harness","bp":"upper legs","eq":"weighted","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.","Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees."],"src":"fedb","img":"fedb/Sled_Drag_-_Harness/0.jpg","img2":"fedb/Sled_Drag_-_Harness/1.jpg"},
{"id":"fe_4276887b","n":"sled overhead backward walk","bp":"shoulders","eq":"weighted","tg":"delts","mg":"calves","sm":["calves","upper back","quadriceps"],"st":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.","Walk backwards, keeping your arms raised above your head. Avoid jerky movements."],"src":"fedb","img":"fedb/Sled_Overhead_Backward_Walk/0.jpg","img2":"fedb/Sled_Overhead_Backward_Walk/1.jpg"},
{"id":"fe_b329a309","n":"sled overhead triceps extension","bp":"upper arms","eq":"weighted","tg":"triceps","sm":[],"st":["Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.","Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.","Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.","Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability."],"src":"fedb","img":"fedb/Sled_Overhead_Triceps_Extension/0.jpg","img2":"fedb/Sled_Overhead_Triceps_Extension/1.jpg"},
{"id":"fe_b0db9ee4","n":"sled push","bp":"upper legs","eq":"weighted","tg":"quads","mg":"calves","sm":["calves","chest","glutes","hamstrings","triceps"],"st":["Load your pushing sled with the desired weight.","Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain."],"src":"fedb","img":"fedb/Sled_Push/0.jpg","img2":"fedb/Sled_Push/1.jpg"},
{"id":"fe_1ac473ae","n":"sled reverse flye","bp":"shoulders","eq":"weighted","tg":"delts","sm":[],"st":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.","Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.","Return to the starting position, taking a couple steps back to take the slack out of the line."],"src":"fedb","img":"fedb/Sled_Reverse_Flye/0.jpg","img2":"fedb/Sled_Reverse_Flye/1.jpg"},
{"id":"fe_53f370cd","n":"sled row","bp":"back","eq":"weighted","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.","With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.","To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.","Take a step or two back to get tension in the line and repeat."],"src":"fedb","img":"fedb/Sled_Row/0.jpg","img2":"fedb/Sled_Row/1.jpg"},
{"id":"fe_c7c4afee","n":"sledgehammer swings","bp":"waist","eq":"hammer","tg":"abs","mg":"calves","sm":["calves","forearms","lats","upper back","shoulders"],"st":["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."],"src":"fedb","img":"fedb/Sledgehammer_Swings/0.jpg","img2":"fedb/Sledgehammer_Swings/1.jpg"},
{"id":"fe_5ddadac2","n":"smith machine hang power clean","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps","shoulders","traps"],"st":["Position the bar at knee height and load it to an appropriate weight.","Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.","Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.","Upon full extension, rebend the hips and knees to lower your receiving position.","Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.","Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement."],"src":"fedb","img":"fedb/Smith_Machine_Hang_Power_Clean/0.jpg","img2":"fedb/Smith_Machine_Hang_Power_Clean/1.jpg"},
{"id":"fe_3ffcd6ca","n":"smith machine stiff-legged deadlift","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Smith_Machine_Stiff-Legged_Deadlift/0.jpg","img2":"fedb/Smith_Machine_Stiff-Legged_Deadlift/1.jpg"},
{"id":"fe_cf79d00d","n":"snatch","bp":"upper legs","eq":"barbell","tg":"quads","mg":"biceps","sm":["biceps","glutes","hamstrings","lower back","shoulders","traps","triceps"],"st":["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.","Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.","Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.","Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."],"src":"fedb","img":"fedb/Snatch/0.jpg","img2":"fedb/Snatch/1.jpg"},
{"id":"fe_0aa5476a","n":"snatch balance","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","shoulders","triceps"],"st":["Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.","Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.","Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.","Continue to descend to full depth, and return to a standing position. Carefully lower the weight."],"src":"fedb","img":"fedb/Snatch_Balance/0.jpg","img2":"fedb/Snatch_Balance/1.jpg"},
{"id":"fe_e9e581b0","n":"snatch deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"forearms","sm":["forearms","glutes","lower back","quadriceps","traps"],"st":["The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.","Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.","At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion."],"src":"fedb","img":"fedb/Snatch_Deadlift/0.jpg","img2":"fedb/Snatch_Deadlift/1.jpg"},
{"id":"fe_c44b1b2c","n":"snatch shrug","bp":"back","eq":"barbell","tg":"traps","mg":"forearms","sm":["forearms","shoulders"],"st":["Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down."],"src":"fedb","img":"fedb/Snatch_Shrug/0.jpg","img2":"fedb/Snatch_Shrug/1.jpg"},
{"id":"fe_2b8bb082","n":"snatch from blocks","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"st":["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."],"src":"fedb","img":"fedb/Snatch_from_Blocks/0.jpg","img2":"fedb/Snatch_from_Blocks/1.jpg"},
{"id":"fe_806d55f5","n":"speed band overhead triceps","bp":"upper arms","eq":"band","tg":"triceps","sm":[],"st":["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.","To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."],"src":"fedb","img":"fedb/Speed_Band_Overhead_Triceps/0.jpg","img2":"fedb/Speed_Band_Overhead_Triceps/1.jpg"},
{"id":"fe_db8f2c8e","n":"spinal stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","lower back","traps"],"st":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"src":"fedb","img":"fedb/Spinal_Stretch/0.jpg","img2":"fedb/Spinal_Stretch/1.jpg"},
{"id":"fe_f2e0efe3","n":"split clean","bp":"upper legs","eq":"barbell","tg":"quads","mg":"calves","sm":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"st":["With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.","Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up."],"src":"fedb","img":"fedb/Split_Clean/0.jpg","img2":"fedb/Split_Clean/1.jpg"},
{"id":"fe_92691bbd","n":"split jerk","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","triceps"],"st":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.","Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.","Return to a standing position, bringing the feet together."],"src":"fedb","img":"fedb/Split_Jerk/0.jpg","img2":"fedb/Split_Jerk/1.jpg"},
{"id":"fe_002781c5","n":"split jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings"],"st":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."],"src":"fedb","img":"fedb/Split_Jump/0.jpg","img2":"fedb/Split_Jump/1.jpg"},
{"id":"fe_86c8b0dc","n":"split snatch","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"calves","sm":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps","triceps"],"st":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.","Carefully return the weight to floor."],"src":"fedb","img":"fedb/Split_Snatch/0.jpg","img2":"fedb/Split_Snatch/1.jpg"},
{"id":"fe_af67e792","n":"squat with chains","bp":"upper legs","eq":"barbell","tg":"quads","mg":"inner thighs","sm":["inner thighs","calves","glutes","hamstrings","lower back"],"st":["To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"src":"fedb","img":"fedb/Squat_with_Chains/0.jpg","img2":"fedb/Squat_with_Chains/1.jpg"},
{"id":"fe_2fd0ed7e","n":"squat with plate movers","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.","Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.","Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.","Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.","Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.","At the top of the movement, side step, bringing your feet together on the opposite side of the plate.","Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.","Place your inside foot on the weight plate, adopting a wide stance for the next repetition."],"src":"fedb","img":"fedb/Squat_with_Plate_Movers/0.jpg","img2":"fedb/Squat_with_Plate_Movers/1.jpg"},
{"id":"fe_e9921cee","n":"standing biceps stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"chest","sm":["chest","shoulders"],"st":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."],"src":"fedb","img":"fedb/Standing_Biceps_Stretch/0.jpg","img2":"fedb/Standing_Biceps_Stretch/1.jpg"},
{"id":"fe_1a815e46","n":"standing cable chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.","Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."],"src":"fedb","img":"fedb/Standing_Cable_Chest_Press/0.jpg","img2":"fedb/Standing_Cable_Chest_Press/1.jpg"},
{"id":"fe_1505efd0","n":"standing cable wood chop","bp":"waist","eq":"cable","tg":"abs","mg":"shoulders","sm":["shoulders"],"st":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"src":"fedb","img":"fedb/Standing_Cable_Wood_Chop/0.jpg","img2":"fedb/Standing_Cable_Wood_Chop/1.jpg"},
{"id":"fe_cc5e6b72","n":"standing elevated quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."],"src":"fedb","img":"fedb/Standing_Elevated_Quad_Stretch/0.jpg","img2":"fedb/Standing_Elevated_Quad_Stretch/1.jpg"},
{"id":"fe_6a9deac0","n":"standing hip circles","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"inner thighs","sm":["inner thighs"],"st":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"src":"fedb","img":"fedb/Standing_Hip_Circles/0.jpg","img2":"fedb/Standing_Hip_Circles/1.jpg"},
{"id":"fe_208fbae1","n":"standing hip flexors","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can't get a thorough, deep stretch in this position, however, because it's hard to relax the hip flexor and stand on it at the same time. Switch sides."],"src":"fedb","img":"fedb/Standing_Hip_Flexors/0.jpg","img2":"fedb/Standing_Hip_Flexors/1.jpg"},
{"id":"fe_04d51221","n":"standing leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","sm":[],"st":["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."],"src":"fedb","img":"fedb/Standing_Leg_Curl/0.jpg","img2":"fedb/Standing_Leg_Curl/1.jpg"},
{"id":"fe_dba3ec42","n":"standing low-pulley deltoid raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"forearms","sm":["forearms"],"st":["Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.","Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"src":"fedb","img":"fedb/Standing_Low-Pulley_Deltoid_Raise/0.jpg","img2":"fedb/Standing_Low-Pulley_Deltoid_Raise/1.jpg"},
{"id":"fe_2792e209","n":"standing palms-up barbell behind the back wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","sm":[],"st":["Start by standing straight and holding a barbell behind your glutes at arm's length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.","Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you."],"src":"fedb","img":"fedb/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg","img2":"fedb/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg"},
{"id":"fe_f0962113","n":"standing soleus and achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"src":"fedb","img":"fedb/Standing_Soleus_And_Achilles_Stretch/0.jpg","img2":"fedb/Standing_Soleus_And_Achilles_Stretch/1.jpg"},
{"id":"fe_d40cf4a5","n":"standing two-arm overhead throw","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"chest","sm":["chest","lats"],"st":["Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."],"src":"fedb","img":"fedb/Standing_Two-Arm_Overhead_Throw/0.jpg","img2":"fedb/Standing_Two-Arm_Overhead_Throw/1.jpg"},
{"id":"fe_e1a85370","n":"step-up with knee raise","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"src":"fedb","img":"fedb/Step-up_with_Knee_Raise/0.jpg","img2":"fedb/Step-up_with_Knee_Raise/1.jpg"},
{"id":"fe_b9e20b65","n":"stomach vacuum","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."],"src":"fedb","img":"fedb/Stomach_Vacuum/0.jpg","img2":"fedb/Stomach_Vacuum/1.jpg"},
{"id":"fe_1cef0e2c","n":"straight bar bench mid rows","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.","Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.","After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."],"src":"fedb","img":"fedb/Straight_Bar_Bench_Mid_Rows/0.jpg","img2":"fedb/Straight_Bar_Bench_Mid_Rows/1.jpg"},
{"id":"fe_9cefc74c","n":"straight raises on incline bench","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps"],"st":["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.","To begin, raise the barbell out in front of your head while keeping your arms extended.","Return to the starting position."],"src":"fedb","img":"fedb/Straight_Raises_on_Incline_Bench/0.jpg","img2":"fedb/Straight_Raises_on_Incline_Bench/1.jpg"},
{"id":"fe_a53049d0","n":"stride jump crossover","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","inner thighs","calves","hamstrings"],"st":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.","Repeat the movement, crossing back over to the other side."],"src":"fedb","img":"fedb/Stride_Jump_Crossover/0.jpg","img2":"fedb/Stride_Jump_Crossover/1.jpg"},
{"id":"fe_56b13a36","n":"superman","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"src":"fedb","img":"fedb/Superman/0.jpg","img2":"fedb/Superman/1.jpg"},
{"id":"fe_25fe4647","n":"supine one-arm overhead throw","bp":"waist","eq":"medicine ball","tg":"abs","mg":"chest","sm":["chest","lats","shoulders"],"st":["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"src":"fedb","img":"fedb/Supine_One-Arm_Overhead_Throw/0.jpg","img2":"fedb/Supine_One-Arm_Overhead_Throw/1.jpg"},
{"id":"fe_2bfb85d5","n":"t-bar row with handle","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","lats"],"st":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"src":"fedb","img":"fedb/T-Bar_Row_with_Handle/0.jpg","img2":"fedb/T-Bar_Row_with_Handle/1.jpg"},
{"id":"fe_58e661ba","n":"the straddle","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"inner thighs","sm":["inner thighs","calves"],"st":["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."],"src":"fedb","img":"fedb/The_Straddle/0.jpg","img2":"fedb/The_Straddle/1.jpg"},
{"id":"fe_2b02231f","n":"toe touchers","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Toe_Touchers/0.jpg","img2":"fedb/Toe_Touchers/1.jpg"},
{"id":"fe_2f089211","n":"torso rotation","bp":"waist","eq":"stability ball","tg":"abs","sm":[],"st":["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."],"src":"fedb","img":"fedb/Torso_Rotation/0.jpg","img2":"fedb/Torso_Rotation/1.jpg"},
{"id":"fe_57cf0633","n":"upper back-leg grab","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","upper back"],"st":["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them."],"src":"fedb","img":"fedb/Upper_Back-Leg_Grab/0.jpg","img2":"fedb/Upper_Back-Leg_Grab/1.jpg"},
{"id":"fe_2b220bd7","n":"upright row - with bands","bp":"back","eq":"band","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Upright_Row_-_With_Bands/0.jpg","img2":"fedb/Upright_Row_-_With_Bands/1.jpg"},
{"id":"fe_50347d50","n":"upward stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","lats"],"st":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."],"src":"fedb","img":"fedb/Upward_Stretch/0.jpg","img2":"fedb/Upward_Stretch/1.jpg"},
{"id":"fe_742b4a69","n":"v-bar pullup","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","shoulders"],"st":["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.","Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"src":"fedb","img":"fedb/V-Bar_Pullup/0.jpg","img2":"fedb/V-Bar_Pullup/1.jpg"},
{"id":"fe_f6fba75b","n":"vertical swing","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","shoulders"],"st":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."],"src":"fedb","img":"fedb/Vertical_Swing/0.jpg","img2":"fedb/Vertical_Swing/1.jpg"},
{"id":"fe_689c9fb3","n":"weighted ball hyperextension","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back"],"st":["To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.","Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.","Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"src":"fedb","img":"fedb/Weighted_Ball_Hyperextension/0.jpg","img2":"fedb/Weighted_Ball_Hyperextension/1.jpg"},
{"id":"fe_8119824a","n":"weighted ball side bend","bp":"waist","eq":"stability ball","tg":"abs","sm":[],"st":["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.","Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch sides and repeat the exercise."],"src":"fedb","img":"fedb/Weighted_Ball_Side_Bend/0.jpg","img2":"fedb/Weighted_Ball_Side_Bend/1.jpg"},
{"id":"fe_31b14764","n":"weighted sit-ups - with bands","bp":"waist","eq":"band","tg":"abs","sm":[],"st":["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"src":"fedb","img":"fedb/Weighted_Sit-Ups_-_With_Bands/0.jpg","img2":"fedb/Weighted_Sit-Ups_-_With_Bands/1.jpg"},
{"id":"fe_05a78a6f","n":"wide stance stiff legs","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"inner thighs","sm":["inner thighs","glutes","lower back"],"st":["Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.","Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor."],"src":"fedb","img":"fedb/Wide_Stance_Stiff_Legs/0.jpg","img2":"fedb/Wide_Stance_Stiff_Legs/1.jpg"},
{"id":"fe_850c44b5","n":"windmills","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."],"src":"fedb","img":"fedb/Windmills/0.jpg","img2":"fedb/Windmills/1.jpg"},
{"id":"fe_e19751d6","n":"wrist rotations with straight bar","bp":"lower arms","eq":"barbell","tg":"forearms","sm":[],"st":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.","Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.","Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure."],"src":"fedb","img":"fedb/Wrist_Rotations_with_Straight_Bar/0.jpg","img2":"fedb/Wrist_Rotations_with_Straight_Bar/1.jpg"},
{"id":"fe_602efec2","n":"yoke walk","bp":"upper legs","eq":"weighted","tg":"quads","mg":"abdominals","sm":["abdominals","glutes","inner thighs","calves","hamstrings","lower back"],"st":["The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.","Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.","Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet."],"src":"fedb","img":"fedb/Yoke_Walk/0.jpg","img2":"fedb/Yoke_Walk/1.jpg"},
{"id":"lh_e80062ec","n":"one-handed cross-body curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand up, leaning slightly forward from a straight position, feet shoulder-width apart, and your knees slightly bent.","Hold a dumbbell in each hand, with your palms facing your body and arms fully extended at your sides. This is your starting position.","Keeping your elbows close to your body, slowly curl one dumbbell up toward your opposite shoulder, across your body.","Continue curling until the weight comes close to the activating bicep's shoulder. Squeeze your bicep before slowly lowering the weight to the starting position.","Repeat the curl on the opposite side.","Continue alternating curls on each side for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_6b8bbe7e","n":"frog pumps","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Lie on your back with your knees bent and your feet flat on the ground. Keep your feet close together and your heels touching.","Bring your feet up towards your hips along the ground until they're about 6 inches apart, and then let your knees fall out to the sides so that your feet are touching each other. This is the starting position.","Engage your glutes and lift your hips up towards the ceiling as high as you can, making sure to keep your feet and knees in the same position.","Hold the top position for 1-2 seconds, then slowly lower your hips to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_53a44f77","n":"lying windshield wiper","bp":"waist","eq":"body weight","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Lie flat on your back with your arms extended out to the sides, palms down, and your legs extended straight up towards the ceiling.","Keep your feet together and engage your core muscles by drawing your navel towards your spine.","Lower your legs to one side, keeping them straight and close to the floor without touching it.","Pause briefly and then lift your legs back up to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of reps or time."],"src":"longhaul"},
{"id":"lh_9d1519c8","n":"one-legged glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Start by lying on your back with your knees bent and feet flat on the ground.","Lift your right leg off the ground and extend it straight up towards the ceiling.","Press your left foot into the ground and lift your hips up towards the ceiling.","Pause at the top of the movement and squeeze your glutes.","Lower your hips back down to the ground and repeat for the desired number of reps.","Switch legs and repeat the exercise on the other side."],"src":"longhaul"},
{"id":"lh_5299ed17","n":"bosu burpee","bp":"chest","eq":"bosu ball","tg":"pectorals","mg":"glutes","sm":["glutes","quadriceps","shoulders","abdominals","traps"],"st":["Start in a standing position with the BOSU ball on the ground (inflated-side down) in front of you.","Grip the edges of the BOSU ball and jump your feet back into a plank position.","Perform a push-up while gripping the BOSU ball.","Jump your feet back towards the BOSU ball into a low squat position.","Complete the squat by standing up. As you rise, lift the BOSU ball overhead, extending your arms towards the ceiling.","Repeat the exercise for desired number of reps."],"src":"longhaul"},
{"id":"lh_af9bc770","n":"bosu plank","bp":"waist","eq":"bosu ball","tg":"abs","mg":"lower back","sm":["lower back","obliques","shoulders"],"st":["Place a BOSU ball on the ground with the flat side facing up.","Assume a plank position with your forearms on the BOSU ball and your toes on the ground.","Engage your core and keep your body in a straight line from head to heels.","Hold the position for the desired amount of time.","Release the position by lowering your knees to the ground."],"src":"longhaul"},
{"id":"lh_fb5b02eb","n":"machine glute kickback","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Adjust the machine to fit your body height","Position yourself in the machine with your hands on the handles and one ankle on the padding.","Keeping your core engaged, exhale and extend your leg back as far as possible while squeezing your glutes.","Inhale and slowly return your leg to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_a3a920dc","n":"barbell pause squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"lower back","sm":["lower back","quadriceps","inner thighs","calves"],"st":["Start with your feet shoulder-width apart, your toes pointing slightly outward, and the barbell on your shoulders.","Lower your body into a squat position, keeping your back straight and your knees tracking with your toes.","Pause at the bottom of the squat for 2-3 seconds.","Slowly rise back up to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_b4f73a3a","n":"eccentric heel drop","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Stand on a raised platform or step with the balls of your feet on the edge and your heels hanging off.","Raise your heels up as high as possible with both feet.","Shift your weight onto one leg and slowly lower your heel down below the platform, only using the single leg.","Use both feet to push yourself back up to the raised position.","Switch your weight to the other foot and lower yourself down single-legged.","Continue alternating sides for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_ca47ae3b","n":"belt squat","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves"],"st":["Add your desired weight to the machine.","Attach a belt or harness around your waist.","Attach a cable or chain to the belt or harness.","Stand on a platform or box with feet shoulder-width apart.","Hold onto a stable object for balance.","Squat by bending the knees and hips while keeping the back straight.","Pause at the bottom of the squat and then push up through the legs to return to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_ff5877ba","n":"hang power clean","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"lower back","sm":["lower back","forearms","hamstrings","inner thighs","traps"],"st":["Stand with feet shoulder-width apart, gripping a barbell at thigh level with palms facing you. This is your starting position.","Bend your knees slightly and hinge at the waist to bring the barbell just above knee level.","Keep your back straight and core tight.","Explosively extend your hips and knees. At the same time, shrug your shoulders and pull the barbell up along your body.","As the barbell reaches chest height, rotate your wrists under the bar and push your body slightly under it.","Catch the bar on the front part of your shoulders with a slight bend in your knees (higher than a full squat).","Stand up fully with the barbell in the front rack position.","Lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_81b44c71","n":"landmine squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves"],"st":["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.","Stand facing the barbell with your feet shoulder-width apart and your toes pointing slightly outward.","Grab the end of the barbell with both hands and lift it up to your chest.","Lower your hips down and back, keeping your chest up and your back straight.","Bend your knees and lower your body until your thighs are parallel to the ground.","Push through your heels and stand back up to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_bd79b5b6","n":"ring (feet) push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","abdominals"],"st":["Start in a plank position with your feet in the rings and your hands shoulder-width apart on the ground.","Lower your body towards the ground by bending your elbows and keeping your body straight.","Push yourself back up to the starting position by straightening your arms.","Repeat."],"src":"longhaul"},
{"id":"lh_97e30ada","n":"band lateral walk","bp":"upper legs","eq":"band","tg":"glutes","mg":"calves","sm":["calves","hamstrings","quadriceps","inner thighs"],"st":["Place a resistance band around your ankles and stand with your feet hip-width apart.","Take a step to the right with your right foot, keeping tension on the band.","Bring your left foot to meet your right foot, maintaining tension on the band.","Take another step to the right with your right foot, again keeping tension on the band.","Repeat this lateral movement for a desired number of steps to the right.","Then, reverse the movement and take the same number of steps to the left."],"src":"longhaul"},
{"id":"lh_0ea69908","n":"kneeling side plank","bp":"waist","eq":"body weight","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["From a kneeling position on the ground, lean to the right until your right hand or elbow make contact with the ground directly under your right shoulder.","Your body should form a straight line from your left shoulder (pointing towards the ceiling) to your left knee that stacked on top of the right knee.","Hold this position, engaging your core, for the desired time.","Raise back up to a kneeling position and repeat on the other side."],"src":"longhaul"},
{"id":"lh_ecb1dff3","n":"one-handed plate pinch","bp":"lower arms","eq":"weighted","tg":"forearms","sm":[],"st":["Choose two weight plates of the same size and weight.","Stand facing the plates and place them on the ground.","Bend down and grip the top of each plate with your fingers and thumbs.","Lift the plates off the ground and hold them beside your body with your arms hanging, elbows straight, but not locked.","Squeeze your fingers and thumbs together to maintain a strong grip on the plates.","Hold the plates for a set amount of time. Consider each second one \"repetition\".","Lower the plates back to the ground and release your grip."],"src":"longhaul"},
{"id":"lh_4a282081","n":"barbell wrist extension","bp":"lower arms","eq":"barbell","tg":"forearms","sm":[],"st":["Hold a barbell with an overhand grip, with your hands shoulder-width apart.","Sit on a bench with your feet shoulder-width apart.","Rest the barbell on the top of your thighs, with your palms facing down.","Slowly lift the barbell by extending your wrists, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearms.","Hold the barbell at the top of the movement for a moment.","Lower the barbell back down to the starting position by flexing your wrists.","Repeat."],"src":"longhaul"},
{"id":"lh_3d5fd5e9","n":"monkey row","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"biceps","sm":["biceps","traps"],"st":["Start in a standing position with your feet shoulder-width apart and your knees slightly bent.","Hold a dumbbell in each hand with your palms facing each other and your arms extended by your sides.","Bend your elbows and pull the dumbbells up towards your armpits, keeping your elbows close to your body.","Pause at the top of the movement and squeeze your shoulder blades together.","Lower the dumbbells back down to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_85eec0be","n":"one-legged hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Begin by lying on your back with your knees bent and feet flat on the ground.","Extend one leg straight out, keeping it in line with your hip.","Place your hands on the ground by your sides for support.","Engage your glutes and lift your hips up towards the ceiling, keeping your extended leg straight.","Pause at the top of the movement, then slowly lower your hips back down to the ground.","Repeat for the desired number of reps, then switch legs."],"src":"longhaul"},
{"id":"lh_104fdf44","n":"torso rotation machine","bp":"waist","eq":"leverage machine","tg":"abs","sm":[],"st":["Adjust the seat and chest pad of the machine.","Kneel on the knee pad with your chest against the chest pad.","Grasp the handles with both hands and keep your elbows bent.","Rotate your torso to the left as far as you comfortably can, while keeping your hips and legs stationary.","Pause briefly at the end of the range of motion, then rotate your torso back to the starting position.","Repeat the rotation to the right side, and continue alternating sides for the desired number of repetitions or time."],"src":"longhaul"},
{"id":"lh_be29bb17","n":"lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Step forward with one leg, bending your knee until your thigh is parallel to the ground.","Keep your back straight and your core engaged.","Push through your front heel to return to the starting position.","Repeat with the other leg."],"src":"longhaul"},
{"id":"lh_78bb1a50","n":"dumbbell horizontal internal shoulder rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","sm":[],"st":["Lie on your back on a flat surface with a dumbbell nearby.","Raise one arm at the shoulder joint to your side so that your upper arm is perpendicular to your body. Bend your elbow at a 90-degree angle bringing your forearm perpendicular to the upper arm so that your hand is above your head on your supporting surface. This position is commonly known as as a single-arm \"cactus pose\".","Hold a dumbbell in your hand with your palm facing up towards the ceiling.","Slowly rotate your arm up towards the ceiling until it's perpendicular to the ground, keeping your elbow bent and your upper arm stationary.","Pause for a moment at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat the exercise with your other arm."],"src":"longhaul"},
{"id":"lh_b8379230","n":"bar hang","bp":"lower arms","eq":"body weight","tg":"forearms","sm":[],"st":["Find a sturdy horizontal bar that can support your body weight.","Stand facing the bar and reach up to grab it with both hands, palms facing away from your body.","Jump or step up to lift your feet off the ground and hang from the bar with your arms fully extended.","Engage your shoulder blades and core muscles to maintain a stable position.","Hold the position for a desired amount of time.","To release, slowly lower your body down and step or jump off the bar."],"src":"longhaul"},
{"id":"lh_647de8d8","n":"shallow lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","hamstrings"],"st":["Stand with your feet shoulder-width apart and your hands on your hips.","Step forward with one leg, bending your knee until your thigh is parallel to the ground.","Keep your back straight and your core engaged.","Push through your front heel to return to the starting position.","Repeat with the other leg."],"src":"longhaul"},
{"id":"lh_bd66eca1","n":"hanging knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"forearms","sm":["forearms","obliques"],"st":["Hang from a pull-up bar with both hands using an overhand grip.","Keep your arms and legs straight with feet off the ground.","Stabilize your torso by engaging your core and slightly retracting your shoulders.","While exhaling, slowly raise your knees toward your chest. Imagine bringing your knees to your nipples.","Pause momentarily when your thighs reach your chest.","Inhale as you lower your legs back down, slowly and controlled, to the starting position."],"src":"longhaul"},
{"id":"lh_aeddcaee","n":"barbell push press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"glutes","sm":["glutes","lower back","quadriceps","traps","triceps"],"st":["Start with the barbell resting on your front shoulders, with your feet shoulder-width apart.","Bend your knees slightly and dip your hips down, then explosively extend your legs and push the barbell up overhead.","As the barbell reaches the top of the movement, press it up and lock out your arms.","Lower the barbell back down to your shoulders and repeat for the desired number of reps."],"src":"longhaul"},
{"id":"lh_c0da3449","n":"band horizontal wood chop","bp":"waist","eq":"band","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Attach a resistance band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with feet shoulder-width apart and knees slightly bent.","Hold the resistance band with both hands and extend arms out in front of the body.","Rotate the torso and pull the band across the body towards the opposite hip.","Keep the arms straight and engage the core muscles throughout the movement.","Slowly return to the starting position","Repeat."],"src":"longhaul"},
{"id":"lh_a67dc2e0","n":"band side kicks","bp":"upper legs","eq":"band","tg":"abductors","sm":[],"st":["Stand with your feet hip-width apart and a resistance band around your ankles.","Engage your core and lift one leg out to the side, keeping it straight and the foot flexed.","Pause at the top of the movement, then slowly lower the leg back down to the starting position.","Repeat for the desired number of reps, then switch sides."],"src":"longhaul"},
{"id":"lh_19bebecc","n":"roll-up","bp":"waist","eq":"body weight","tg":"abs","sm":[],"st":["Lie on your back with your arms extended overhead and your legs straight.","Engage your core and slowly lift your head, neck, and shoulders off the ground.","Continue to roll up, reaching your arms towards your toes and keeping your legs straight.","Pause at the top of the movement, then slowly roll back down to the starting position.","Repeat."],"src":"longhaul"},
{"id":"lh_16411171","n":"gripper","bp":"lower arms","eq":"weighted","tg":"forearms","sm":[],"st":["Adjust the gripper machine to the desired resistance level.","Hold the gripper in one hand with a firm grip, making sure your fingers are comfortably positioned on the handles.","Keep your wrist and forearm in a neutral position to avoid unnecessary strain.","Start by squeezing the handles together using your hand strength.","Continue to squeeze the handles as forcefully as you can, engaging your grip muscles.","Hold the maximum contraction for a few seconds to fully activate your muscles.","Slowly release the tension and allow the handles to return to the starting position.","Repeat the squeezing and releasing motion for the desired number of repetitions.","Switch to the other hand and repeat the exercise to work both hands equally."],"src":"longhaul"},
{"id":"lh_facda989","n":"towel pull-up","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"lats","sm":["lats","biceps","rotator cuff","rear deltoids"],"st":["Find a sturdy horizontal bar that can support your body weight.","Fold a single large towel or two hand towels in half and drape them over the bar.","Grab the ends of the towel with both hands, palms facing each other.","Hang from the bar with your arms fully extended and your feet off the ground.","Pull yourself up towards the bar by bending your elbows and squeezing your shoulder blades together.","Pause at the top of the movement, with your chin above the bar.","Lower yourself back down to the starting position with control.","Repeat for desired number of repetitions."],"src":"longhaul"},
{"id":"lh_f89aa9c5","n":"machine hip thrust","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Adjust the machine to the appropriate height and resistance level.","Sit on the machine with your back against the backrest and your feet flat on the foot platform.","Engage your core and glutes, then press through your heels to extend your hips forward.","Continue to drive your hips forward until your body is in a straight line from your knees to your shoulders.","Hold the position for a brief moment, focusing on squeezing your glutes.","Slowly lower your hips back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_6c3474cb","n":"seated snatch grip behind the neck press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Start by sitting on a bench with a backrest, next to a racked, weighted barbell.","Grip the barbell with a wide snatch grip.","Position the barbell behind your neck, resting it on your upper traps.","Engage your core and keep your back straight.","Press the barbell overhead by extending your arms and pushing the weight up.","Lock out your elbows at the top of the movement.","Lower the barbell back down to the starting position behind your neck.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_fcfe2d1b","n":"floor back extension","bp":"back","eq":"body weight","tg":"spine","sm":[],"st":["Lie face down on the floor with your legs extended and your arms by your sides.","Place your hands on the back of your head, or keep them out in a \"cactus pose\".","Engage your core muscles by drawing your navel towards your spine.","Slowly lift your upper body off the floor, using your lower back muscles.","Keep your neck in a neutral position and avoid straining or arching it.","Hold the lifted position long enough to squeeze your lower back muscles.","Lower your upper body back down to the starting position in a controlled manner.","Repeat the exercise for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_86fea814","n":"standing cable leg curl","bp":"upper legs","eq":"cable","tg":"hamstrings","sm":[],"st":["Stand facing a cable machine with your feet hip-width apart.","Attach an ankle cuff to your right ankle.","Hold onto the machine for support and balance.","Bend your right knee and bring your heel towards your glutes, keeping your upper leg stationary.","Squeeze your hamstring at the top of the movement.","Slowly lower your leg back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and perform the exercise with your left leg."],"src":"longhaul"},
{"id":"lh_31cd0501","n":"bulgarian split squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs"],"st":["Stand with your back facing a bench or step.","Place the top of one foot on the bench or step behind you.","Bend your front knee and lower your body down towards the ground, keeping your back straight.","Pause when your front thigh is parallel to the ground.","Push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"src":"longhaul"},
{"id":"lh_b567f204","n":"one-legged balance","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Stand tall with your feet hip-width apart.","Shift your weight onto one leg and lift the other leg off the ground.","Engage your core muscles to maintain balance.","Keep your standing leg slightly bent and your knee aligned with your toes.","Find a focal point to help you maintain balance and focus.","Hold the position for a desired amount of time.","Switch legs and repeat the exercise."],"src":"longhaul"},
{"id":"lh_d6ac96ab","n":"barbell feet-up bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie flat on a bench with your feet up in the air, knees bent at a 90-degree angle.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and press your lower back into the bench.","Unrack the barbell and hold it directly above your chest, arms fully extended.","Inhale and slowly lower the barbell towards your chest, keeping your elbows tucked in.","Pause for a brief moment when the barbell touches your chest.","Exhale and push the barbell back up to the starting position, fully extending your arms.","Repeat the movement for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_22b25f72","n":"one-handed plate wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","sm":[],"st":["Start by sitting on a bench or chair with your feet flat on the ground.","Hold a weight plate with an underhand grip, placing your hand on the inside rim of the plate.","Rest your forearm on your thigh, with your wrist hanging off the edge and pointing to the ceiling.","Lower the weight plate towards the ground by flexing your wrist, keeping your forearm stationary.","Pause for a moment at the bottom of the movement, feeling the stretch in your wrist.","Slowly curl the weight plate back up towards your body.","Repeat for the desired number of reps and then switch sides."],"src":"longhaul"},
{"id":"lh_ad4d02e9","n":"seated oblique twist","bp":"waist","eq":"body weight","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Sit on a workout mat or bench with your knees bent and feet flat on the floor.","Engage your core muscles by drawing your navel towards your spine.","Hold a dumbbell or medicine ball with both hands close to your chest.","Keeping your back straight, lean slightly back to engage your abdominal muscles.","Exhale and rotate your torso to the right, bringing the weight towards your right hip.","Inhale as you return to the starting position.","Exhale and rotate your torso to the left, bringing the weight towards your left hip.","Inhale as you return to the starting position.","Repeat the twisting motion for the desired number of repetitions on each side."],"src":"longhaul"},
{"id":"lh_00ddcc87","n":"dumbbell one-handed wrist extension","bp":"lower arms","eq":"dumbbell","tg":"forearms","sm":[],"st":["Hold a dumbbell with an overhand grip.","Sit on a bench with your feet shoulder-width apart.","Rest your forearm on the top of your thigh, with your palm facing down.","Slowly lift the dumbbell by extending your wrist, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearm.","Hold the dumbbell at the top of the movement for a moment.","Lower the dumbbell back down to the starting position by flexing your wrist towards the floor.","Repeat for the desired number of reps and then switch sides."],"src":"longhaul"},
{"id":"lh_364e64c1","n":"one-handed lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms","rotator cuff","rear deltoids"],"st":["Adjust the seat height and position yourself in the lat pulldown machine.","Grasp the lat pulldown bar with one hand, using an overhand grip.","Engage your core and keep your back straight throughout the exercise.","Start with your arm fully extended, allowing the weight to be lifted off the stack.","Exhale and pull the bar down towards your side, focusing on squeezing your lat muscles.","Pause for a moment at the bottom of the movement, feeling the contraction in your lat.","Inhale and slowly return the bar to the starting position, fully extending your arm.","Repeat for the desired number of repetitions and then switch to the other hand."],"src":"longhaul"},
{"id":"lh_16eb22d0","n":"fat bar deadlift","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"glutes","sm":["glutes","hamstrings","lower back","calves","traps","quadriceps"],"st":["Stand with your feet shoulder-width apart, holding a loaded fat bar in front of your quads.","Bend your knees, hinge and lean forward at the hips, keeping your back straight and your chest up.","Lower the fat bar towards the ground, keeping it close to your legs.","Pause when the fat bar is just below your knees.","Push through your heels and stand up, keeping your back straight and your chest up.","Repeat."],"src":"longhaul"},
{"id":"lh_70c30658","n":"band one-handed standing chest fly","bp":"chest","eq":"band","tg":"pectorals","mg":"biceps","sm":["biceps","forearms","shoulders"],"st":["Find a sturdy stationary object, such as a pole or a door anchor, and attach one end of the resistance band to it at chest height.","Stand with your feet shoulder-width apart, facing away from the stationary object.","Hold the free end of the resistance band in one hand, with your palm facing forward.","Position yourself at a distance from the stationary object so that there is tension in the band when your arm is extended forward at chest height.","Keep your elbow slightly bent and your arm extended out to the side at shoulder height.","Engage your core muscles to stabilize your torso.","With a slight bend in your elbow, bring your arm across your chest in a sweeping motion while keeping your chest open.","Feel the stretch in your chest muscles as you bring your arm across your body.","Return your arm to the starting position in a controlled manner.","Complete the desired number of repetitions on one side before switching to the other."],"src":"longhaul"},
{"id":"lh_b63a5240","n":"underhand grip inverted row","bp":"back","eq":"body weight","tg":"lats","mg":"rear deltoids","sm":["rear deltoids","traps","biceps","forearms","rotator cuff"],"st":["Set up a barbell or suspension trainer at waist height.","Stand facing the barbell or suspension trainer and grab it with an underhand grip, hands shoulder-width apart.","Walk your feet forward until your body is at a slight angle, with your arms extended and your body in a straight line.","Engage your core and squeeze your shoulder blades together as you pull your chest towards the barbell or suspension trainer.","Pause for a moment at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_e39cf01a","n":"bosu mountain climbers","bp":"waist","eq":"bosu ball","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Place a BOSU ball on the floor with the dome side facing down.","Assume a push-up position with your hands gripped on the sides of the BOSU ball.","Engage your core and keep your body in a straight line from head to toe.","Start by bringing one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating your knees in a running motion, keeping your hips low and your abs tight.","Perform the exercise for the desired number of repetitions or time."],"src":"longhaul"},
{"id":"lh_d41605a6","n":"standing bicycle crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes","inner thighs","lower back"],"st":["Stand upright with your feet hip-width apart.","Place your hands behind your head, elbows out to the sides.","Engage your core muscles to stabilize your torso.","Lift your right knee towards your chest while simultaneously crunching your left elbow towards your right knee.","Return to the starting position.","Now, lift your left knee towards your chest while crunching your right elbow towards your left knee.","Continue alternating between sides for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_5dc60321","n":"side-lying clamshell","bp":"upper legs","eq":"body weight","tg":"abductors","sm":[],"st":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee as high as you can without moving your pelvis.","Pause for a moment at the top of the movement, then slowly lower your knee back down.","Repeat the movement for the desired number of repetitions, then switch to the other side."],"src":"longhaul"},
{"id":"lh_06efe3dc","n":"fire hydrants","bp":"upper legs","eq":"body weight","tg":"glutes","sm":[],"st":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Engage your core and keep your back straight throughout the exercise.","Keeping your knee bent, lift one leg out to the side, keeping your foot flexed and parallel to the ground.","Pause for a moment at the top of the movement, squeezing your glutes.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"src":"longhaul"},
{"id":"lh_7c2a82e2","n":"barbell pause deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","calves","forearms","traps","quadriceps"],"st":["Stand with your feet hip-width apart and your toes pointing forward.","Bend at the hips and knees to lower your body down, keeping your back straight and your chest lifted.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and lift the barbell off the ground, driving through your heels and keeping your back straight.","Almost immediately during your lift, pause for a brief moment when the barbell is in front of your lower shins, maintaining tension in your muscles.","Continue the lift until you're standing straight.","Lower the barbell back down to the ground, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_b2169655","n":"runner's 5","bp":"lower legs","eq":"body weight","tg":"calves","mg":"glutes","sm":["glutes","hamstrings","quadriceps","inner thighs"],"st":["Stand with your feet hip-width apart. We're going to complete five, one-legged exercises on one side, then the other.","First, One-legged Squats: Stand on one leg with the other leg extended slightly behind you. Slowly lower your body by bending the knee of the standing leg, keeping your back straight and chest up. Lower yourself as far as comfortable while maintaining balance, then return to the starting position. Repeat for the desired number of repetitions.","Second, One-legged Romanian Deadlifts: Stand on one leg with a slight bend in your knee. Keeping your back straight, hinge at your hips to lower your upper body forward while extending the opposite leg straight behind you. Go as low as your flexibility allows, feeling a stretch in your hamstring. Return to the upright position. Repeat for the desired number of repetitions.","Third, One-legged Lunges: Stand on one leg and take a step forward with the other leg. Lower your body by bending both knees until your front thigh is parallel to the ground (or as low as you can comfortably go). Keep your upper body upright, and push through your front heel to return to the starting position. Repeat for the desired number of repetitions.","Fourth, One-legged Sidekicks: Stand on one leg with the other leg slightly lifted to the side. Perform a side kick by extending your lifted leg straight out to the side, then bring it back to the starting position. Maintain balance throughout. Repeat for the desired number of repetitions.","Fifth, One-legged Front-Back Kicks: Stand on one leg with the other leg lifted slightly in front of you. Perform a front kick by extending your lifted leg forward, then immediately perform a back kick by extending it backward. Keep control and balance throughout the movement. Repeat for the desired number of repetitions.","Repeat the five exercises on the other side."],"src":"longhaul"},
{"id":"lh_05444bea","n":"oblique sit-up","bp":"waist","eq":"body weight","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head, with your elbows pointing out to the sides.","Engage your core muscles by pulling your belly button in towards your spine.","Slowly lift your upper body off the ground, twisting to one side, touching one elbow to the opposite knee.","Exhale as you reach the top of the movement and hold for a second.","Lower your upper body back down to the starting position, inhaling as you do so.","Repeat the movement on the other side, twisting to the opposite side.","Continue alternating sides for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_7228a812","n":"trap bar shrug","bp":"back","eq":"trap bar","tg":"traps","mg":"forearms","sm":["forearms"],"st":["Stand inside a trap bar with your feet shoulder-width apart.","Grasp the handles of the trap bar with an overhand grip.","Keep your back straight and your core engaged.","Exhale and lift your shoulders up towards your ears, squeezing your trapezius muscles.","Hold the shrug position for a second.","Inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_7e366f90","n":"half air squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves"],"st":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Engage your core and keep your chest lifted throughout the exercise.","Lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs approach parallel to the ground but do not go any deeper.","Pause for a moment at the bottom of the squat.","Push through your heels and extend your knees and hips to return to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_2361bbde","n":"plate front hold","bp":"shoulders","eq":"weighted","tg":"delts","sm":[],"st":["Stand with your feet shoulder-width apart and hold a weight plate with both hands in front of your chest.","Engage your core and keep your back straight.","Extend your arms fully, keeping your arms parallel to the ground.","Hold this position for the desired amount of time."],"src":"longhaul"},
{"id":"lh_6afa3e71","n":"dumbbell one-handed chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","sm":[],"st":["Start by lying flat on a bench with your feet firmly planted on the ground.","Hold a dumbbell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Inhale and slowly lower the dumbbell towards your chest, keeping your elbow at a 90-degree angle.","Exhale and push the dumbbell back up to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch to the other hand."],"src":"longhaul"},
{"id":"lh_a5525833","n":"rope wave","bp":"upper arms","eq":"rope","tg":"biceps","mg":"forearms","sm":["forearms","rear deltoids","shoulders","traps","abdominals","chest","triceps"],"st":["Stand with your feet shoulder-width apart, knees slightly bent, in front of a heavy rope.","Grip the ends of the rope with both hands. Your palms should be facing inward.","Tighten your core to stabilize your spine.","Begin to raise and lower both arms rapidly in unison. The motion should create waves in the rope.","Keep the waves going consistently for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_576cbf28","n":"dumbbell prone incline front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"chest","sm":["chest","traps"],"st":["Set an incline bench to a 45-degree angle and lie face down with your chest against the bench.","Hold a dumbbell in each hand, palms facing your knees, arms extended towards the ground.","Keep the balls of your feet on the ground and your neck in a neutral position. Brace your core and maintain a straight back throughout the exercise.","With your arms straight except for a slight elbow bend, slowly raise the dumbbells until they are above your head, parallel with your upper body.","Pause briefly at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat the movement for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_fb2197c4","n":"kettlebell kickstand squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","abdominals","calves","obliques"],"st":["Stand with your feet hip-width apart, holding a kettlebell with both hands in front of your chest.","Shift your weight onto your left foot and place your right foot behind you, resting on the ball of your foot – this is your kickstand position.","Hinge your hips back slightly, ensuring a straight back and engaged core.","Bend at your left knee to lower down into a squat, keeping the weight in your left heel and the kettlebell steady in front of your chest.","Lower down until your left thigh is nearly parallel to the ground, or as low as you can go comfortably.","Drive through your left heel to stand back up to the starting position.","Complete the desired number of repetitions on the left side before switching sides and repeating."],"src":"longhaul"},
{"id":"lh_a1c0e7db","n":"landmine one-handed shoulder press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","abdominals","obliques","rotator cuff","traps"],"st":["Position a barbell securely in a landmine attachment or securely in a corner to prevent it from sliding.","Load the desired weight onto the free end of the barbell.","Stand facing the barbell with your feet shoulder-width apart for stability.","Bend slightly to grab the barbell with one hand directly where the barbell is loaded.","Raise the barbell to your shoulder level, switching your grip so that your hand is under the barbell and your palm faces your chin over a bent and tucked elbow. This is your starting position.","Brace your core, and exhale as you press the barbell upward and slightly forward by extending your arm.","Keep your body straight and avoid rotating your hips or shoulders during the press.","Inhale as you slowly return the barbell to the starting position at your shoulder.","Complete all reps on one side before switching hands to work the opposite side."],"src":"longhaul"},
{"id":"lh_8e3e6996","n":"landmine rotation","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","glutes","lower back","rotator cuff","shoulders"],"st":["Place one end of a barbell securely into a landmine attachment or a corner to stabilize it.","Stand with your feet shoulder-width apart, facing the end of the barbell, and grab the end of the bar with both hands.","Press the barbell up and hold it in front of your head with your arms extended, while keeping your elbows slightly bent.","Begin to rotate your torso to one side; as you do, allow your hands holding the barbell to drop towards the hip on the same side as the rotation. During the rotation, keep your arms in the same position, extended with elbows bent, as much as possible.","Simultaneously, allow the foot you are rotating away from to rise up to the ball of the foot at the bottom of the rotation, facilitating a full rotation of the hips.","Reverse the direction and rotate your torso to the opposite side, repeating the arm movement and foot pivot to complete one full repetition.","Continue alternating the rotational movements for the desired number of repetitions, maintaining the appropriate arm and foot mechanics throughout."],"src":"longhaul"},
{"id":"lh_07daed87","n":"step-up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","calves","hamstrings","inner thighs"],"st":["Stand upright with a bench or bench-height platform in front of you, feet hip-width apart.","Place your right foot on the bench, ensuring your entire foot is on the surface.","Press through your right foot to lift your body up onto the bench, bringing your left foot to meet your right foot.","Stand tall on the bench with both feet flat and your core engaged.","Step back down with your left foot, returning to the floor.","Follow by stepping down with your right foot, coming back to the starting position.","Repeat the exercise for the desired number of repetitions before switching to lead with the left foot."],"src":"longhaul"},
{"id":"lh_300ed364","n":"one-handed plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","lower back","obliques"],"st":["Begin in a standard push-up position with your hands on the ground and elbows aligned below your shoulders, and your body forming a straight line from your head to your heels.","Spread your legs slightly wider than hip-width apart to provide additional stability.","Shift your weight onto your left hand as you slowly lift your right hand off the ground, wrapping it behind your back or under your sternum.","Engage your core, glutes, and thigh muscles to prevent your hips from dropping or rotating.","Hold the one-handed plank for the desired duration, breathing steadily throughout the exercise.","Lower your right hand back to the starting plank position with control.","Repeat the exercise by shifting your weight onto your right hand and wrapping your left hand behind your back or under your sternum."],"src":"longhaul"},
{"id":"lh_ca5f5cb1","n":"sled pull","bp":"lower legs","eq":"weighted","tg":"calves","mg":"glutes","sm":["glutes","hamstrings","quadriceps","abdominals","lower back"],"st":["Adjust the weight on the sled according to your fitness level and training goals.","If using a pulling harness, strap it on securely, making sure it's comfortably snug. If using straps with handles, grip the handles firmly with both hands.","Stand facing the sled with your feet hip-width apart. Make sure you have a smooth, level, unobstructed path behind you.","Lower into a quarter-squat position, keeping your back straight, and brace your core.","Begin walking backwards slowly, taking small steps while keeping the tension on the harness or handles.","Push through the balls of your feet with each step, focusing on engaging your quadriceps, calves, and glutes.","Keep your chest up and shoulders back throughout the movement to maintain proper posture.","Continue pulling the sled for a number of steps or seconds.","Carefully disengage from the harness or place down the handles."],"src":"longhaul"},
{"id":"lh_f997366e","n":"barbell forearm roll-up","bp":"lower arms","eq":"barbell","tg":"forearms","sm":[],"st":["Set up a power rack placing a barbell at about chest height.","Select a kettlebell and an appropriately sized resistance band that can be looped around it.","Loop one end of the resistance band around the kettlebell securely.","Loop the other end of the resistance band around one end of the barbell securely, wrapping it twice to ensure the kettlebell is suspended and the band is taut.","Stand facing the barbell with your feet shoulder-width apart, positioning yourself slightly back to allow full range of motion for the barbell to roll.","Extend your arms forward and grasp the barbell with both hands using an overhand grip, placing your hands slightly wider than shoulder-width for stability. Place one hand on either side of the band connected to the barbell.","Begin with your right hand, rolling the barbell away from you as much as possible to contract your forearm muscles.","After rolling with your right hand, switch to your left hand and perform the same rolling motion, alternating between hands with each roll.","Continue this alternating pattern, rolling the barbell and lifting the kettlebell until you cannot roll any further or the kettlebell reaches its peak height.","Carefully reverse the rolling motion using alternate hands again to lower the kettlebell back to the starting position in a controlled manner."],"src":"longhaul"},
{"id":"lh_7733b575","n":"dumbbell forearm twist","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps"],"st":["Stand up straight with your feet shoulder-width apart.","Hold a dumbbell in each hand and let your arms hang down in front of your quads, palms facing forward, with a slight bend in the elbows.","Curl the dumbbells upwards by bending your elbows, stopping when your forearms are parallel to the ground. This is the starting position.","While keeping your upper arms stationary, rotate your wrists to flip the dumbbells towards each other until your palms face down.","Pause for a moment, then rotate your wrists in the opposite direction, turning the dumbbells back to the starting position.","Repeat the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_d04efa71","n":"dumbbell z press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"abdominals","sm":["abdominals","lower back","rear deltoids","triceps"],"st":["Sit down on the ground, legs extended in front of you and spaced apart for stability.","Hold a dumbbell in each hand at shoulder height, palms facing forward.","Plant your heels firmly on the ground and brace your core.","Press the dumbbells vertically overhead, fully extending your arms without locking your elbows.","Pause briefly at the top of the movement.","Lower the dumbbells back to the starting position at shoulder height in a controlled manner.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_894aa159","n":"barbell z press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"abdominals","sm":["abdominals","lower back","rear deltoids","triceps"],"st":["Position a loaded barbell in a rack a little above knee height.","Sit down on the floor so that the barbell touches your upper chest.","Extend your legs straight in front of you. Ensure your back is straight.","Grip the barbell just outside shoulder width with palms facing forward.","Unrack the barbell so it is positioned in front of your chin with tension on your front shoulders. This is your starting position.","Brace your core. Push your heels into the ground.","Press the barbell upwards until your arms are fully extended, making sure the bar moves in a straight vertical line.","Pause briefly at the top of the movement.","Lower the bar back to the starting position in a controlled manner.","Repeat for the desired number of reps."],"src":"longhaul"},
{"id":"lh_a306d2ab","n":"cable upright downward internal rotation","bp":"shoulders","eq":"cable","tg":"delts","sm":[],"st":["Adjust the pulley on a cable machine to eye-level and attach a handle to it.","Stand facing away from the machine, feet shoulder-width apart.","Grab the handle with one hand, raising your arm so your upper arm is parallel to the ground and your forearm is pointing straight up, creating a 90-degree angle at your elbow.","Brace your core and begin to rotate your hand forward at your shoulder, keeping your upper arm stable and parallel to the ground throughout the movement.","Continue the rotation until your forearm is parallel to the ground, completing the internal rotation.","Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."],"src":"longhaul"},
{"id":"lh_ef7da1eb","n":"cable upright upward external rotation","bp":"shoulders","eq":"cable","tg":"delts","sm":[],"st":["Adjust the pulley on a cable machine to sternum-level and attach a handle to it.","Stand facing the machine, feet shoulder-width apart.","Grab the handle with one hand, palm facing down, keeping your upper arm parallel to the ground and your forearm pointing towards the pulley, also parallel to the ground. This is your starting position.","Begin to rotate your arm at the shoulder, moving your hand upward and backwards, keeping the upper arm stable and parallel to the ground throughout the movement.","Continue the rotation until your forearm is pointing straight up, perpendicular to the ground, maintaining a 90-degree angle at your elbow.","Lower the handle back down to the starting position in a controlled manner.","Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."],"src":"longhaul"},
{"id":"lh_dd21077f","n":"plank pull through","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","lower back","obliques"],"st":["Start in a high plank position with your hands positioned directly under your shoulders, feet slightly wider than hip-width apart, and a dumbbell or kettlebell placed on the floor on one side of your body at sternum-level.","Reach under your torso with your opposite hand to grab the dumbbell.","Pull the weight across the floor to the other side of your body while keeping your hips as stable as possible.","Place the weight on the floor and return your hand to the starting plank position.","Repeat the movement by reaching with the other hand to pull the dumbbell back to the starting side.","Continue alternating sides for the desired number of reps or time duration."],"src":"longhaul"},
{"id":"lh_1a186491","n":"meadows row","bp":"back","eq":"barbell","tg":"lats","mg":"traps","sm":["traps","rear deltoids","lower back","rotator cuff"],"st":["Place one end of a barbell in a corner to secure it, or use a landmine attachment if available.","Stand next to the barbell so it is to your side, with your feet shoulder-width apart.","Bend your knees slightly and hinge at the hips to lean forward, keeping your back straight.","Grasp the barbell with one hand using an overhand grip, just above the weight plates.","Place your other hand on your thigh or knee for support.","Brace your core and row the barbell towards your armpit, keeping your elbow tucked in.","Squeeze your back muscles at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions before switching sides."],"src":"longhaul"},
{"id":"lh_e4fb3924","n":"one-handed high-cable row","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms","rotator cuff","rear deltoids"],"st":["Adjust the cable machine pulley to a position above your head and attach a single handle.","Stand facing the cable machine with your feet shoulder-width apart.","Grab the handle with one hand, palm facing down.","Step back slightly from the cable machine to create tension on the cable. Stretch your arm out in front of you. This is your starting position.","Pull the handle towards your side, keeping your elbow close to your body. Rotate your palm to face your torso as you pull.","Squeeze your back muscles when your hand is near your torso.","Slowly extend your arm to return the handle to the starting position while controlling the weight.","Repeat for the desired number of repetitions before switching arms."],"src":"longhaul"},
{"id":"lh_337b0c23","n":"dumbbell one-handed leaning lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"obliques","sm":["obliques"],"st":["Stand with your feet shoulder-width apart and a dumbbell in your left hand.","Slightly lean your right shoulder against a wall or stable structure. Aim for a 60-degree angle between you and the ground.","Keep your back straight and core engaged. This is your starting position.","Slowly lift the dumbbell to the side, keeping your arm slightly bent. Raise it until your left arm is perpendicular with your body.","Pause at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat the desired number of repetitions before switching to the other side."],"src":"longhaul"},
{"id":"lh_908bec0e","n":"cable horizontal wood chop","bp":"waist","eq":"cable","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Set up the cable machine by adjusting the cable to just under chest height and attach a handle.","Stand perpendicular to the cable machine with your feet shoulder-width apart, keeping your toes and head angled away from the machine.","Grip the handle with both hands, extending your arms fully. Begin with your upper body twisted so that your arms and the handle are positioned on the side closest to the machine, while your head and toes continue to face away.","Step away from the machine to create enough tension in the cable, ensuring it is taut before you start the exercise.","Rotate your torso while keeping your arms straight, moving the handle in a horizontal motion across your body until your hands are aligned forward, matching the direction of your toes and head.","Keep your core engaged throughout the movement to maintain stability and prevent any rotation in your hips or bending of the arms.","Complete the twisting motion until your arms are fully extended in front of you, parallel to the direction your toes and head are facing.","Slowly and with control, reverse the motion, returning to the twisted starting position while maintaining the alignment of your head and toes facing forward."],"src":"longhaul"},
{"id":"lh_e9ef04ae","n":"single-leg v-up","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie flat on your back on a mat with your arms extended overhead and your legs fully extended.","Lift one leg towards a 60-degree angle with the floor while simultaneously raising your upper body, reaching your hands towards the raised foot.","Keep both legs straight, with the non-moving leg remaining on the floor.","Contract your abdominals as you lift your body, aiming to touch your toes with your hands.","Hold the V position momentarily, maintaining balance and stability.","Slowly lower your upper body and leg back to the starting position.","Repeat the movement with the other leg, alternating legs with each repetition."],"src":"longhaul"},
{"id":"lh_b17f9aa1","n":"kettlebell around the world","bp":"waist","eq":"kettlebell","tg":"abs","mg":"abdominals","sm":["abdominals","shoulders"],"st":["Hold the kettlebell in front of your body with arms extended and both hands on the handle.","Move the kettlebell around your body; start by passing it to your right hand and move it behind your back.","Receive the kettlebell with your left hand behind your back, and continue moving it around to the left side and back to the front.","Continue this motion for the desired number of repetitions before switching direction."],"src":"longhaul"},
{"id":"lh_417fd499","n":"dumbbell lu raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","traps"],"st":["Stand with your feet shoulder-width apart, holding a pair of dumbbells at your sides with your palms facing your body.","Lift the dumbbells laterally with a slight bend in the elbows, rotating your thumbs upwards as the weights ascend.","Continue lifting the weights above your head until your arms are fully extended and your thumbs are pointing towards each other.","Pause briefly at the top of the movement.","Lower the dumbbells back to the starting position in a controlled manner, reversing the thumb rotation."],"src":"longhaul"},
{"id":"lh_ce7d4d1d","n":"dumbbell crush grip curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Select a single dumbbell and grip it with both hands, one on each end, pressing your palms against the sides of the dumbbell.","Position yourself straight-armed on a preacher curl bench, ensuring that your elbows and upper arms are comfortably resting against the bench pad. This is your starting position.","Keep pressing your hands together firmly to maintain a 'crush grip' on the dumbbell throughout the exercise.","While maintaining the grip, exhale and curl the dumbbell upwards towards your shoulders, focusing on contracting the biceps.","Hold the contraction briefly at the top of the movement, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl for the desired number of repetitions, ensuring the crush grip is maintained throughout each curl."],"src":"longhaul"},
{"id":"lh_1475f025","n":"dumbbell one-handed hammer isometric hold","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Select a dumbbell of appropriate weight and position yourself at a preacher curl bench.","Stand with one foot forward and the other back in a staggered stance.","Lean slightly forward from the hips and place the back of your upper arm (of the arm that will be curling) on the sloped part of the preacher bench, ensuring your shoulders are open to the side.","Curl your arm up to achieve a 90-degree angle at the elbow. Your forearm should be roughly perpendicular to the floor.","Hold the dumbbell at this angle, maintain the position firmly and ensure the muscle is under constant tension without movement for the desired time period.","Once the hold is complete, slowly lower the dumbbell back to the starting position in a controlled manner.","Repeat the process using the other arm."],"src":"longhaul"},
{"id":"lh_1f6d1828","n":"hanging side-to-side knee drive","bp":"waist","eq":"body weight","tg":"abs","mg":"biceps","sm":["biceps","lats","obliques","forearms"],"st":["Grip the pull-up bar with a supinated grip (palms facing you) and arms fully extended.","Pull yourself up to a halfway pull-up until your upper arms are parallel to the floor. This is the starting position.","Start by cycle your knees towards your chest in a bicycle motion straight in front of you.","Continue the cycling motion as you rotate your hips to the right, then the left, going as far as you can while maintaining the half pull-up. This is one repetition.","Repeat the bicycle and rotating motions for the desired number of repetitions or seconds before lowering yourself to the ground."],"src":"longhaul"},
{"id":"lh_a1a610cd","n":"dumbbell lateral lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves","hamstrings"],"st":["Stand with your feet hip-width apart, holding a dumbbell in each hand at your sides. This is the starting position.","Take a big step out to the right, ensuring your toes on both feet are pointing forward.","Shift your weight over your right leg, hinging at the hip and pushing your buttocks back while bending the right knee. Keep the left leg straight.","Keep your back straight and chest up as you lunge, lowering until your right thigh is parallel to the floor. The dumbbells will lower with your arms on either side of your right calf.","Push off your right foot to return to the starting position.","Repeat for the desired number of repetitions before switching to the left side."],"src":"longhaul"},
{"id":"lh_d91f651d","n":"kettlebell single-arm bottoms-up overhead press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"forearms","sm":["forearms","triceps"],"st":["Stand with feet shoulder-width apart holding a kettlebell bottoms-up in one hand at shoulder height.","Engage your core and make sure your wrist is straight and aligned directly under the kettlebell.","Press the kettlebell overhead by extending your arm fully while keeping the bottom of the kettlebell facing up.","Maintain a stable and upright position without leaning backward or sideways.","Slowly lower the kettlebell back to shoulder height, keeping control of the movement.","Repeat for desired number of reps, then switch to the other arm."],"src":"longhaul"},
{"id":"lh_f92c655f","n":"double kettlebell alternating z press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"abdominals","sm":["abdominals","lower back","rear deltoids","triceps"],"st":["Select two kettlebells of appropriate weight.","Sit on the floor with legs extended in front of you.","Clean the kettlebells to the front rack position.","Engage your core and ensure your spine is neutral.","Press one kettlebell overhead while keeping the other in the front rack position.","Lower the overhead kettlebell back to the front rack position.","Simultaneously press the other kettlebell overhead.","Continue to alternate pressing each kettlebell, creating a 'seesaw' motion.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_661accf4","n":"ring feet-elevated bulgarian row","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"lats","sm":["lats","forearms","rear deltoids","traps"],"st":["Set the gymnastic rings to a suitable height, typically about waist height.","Place a bench or elevated surface in front of you. The top of the surface should be about an arms-length lower than the rings.","Hold onto the rings with an overhand grip and walk your feet forward to place them on the surface.","Hang from the rings with your arms straight, creating a straight line from your feet to your shoulders that is parallel with the floor. This is your starting position.","With your arms extended, pull yourself upwards by bending your elbows and drawing your chest towards the rings.","Squeeze your shoulder blades together at the top of the movement, keeping your body stable.","Slowly extend your arms to lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_21122059","n":"stability ball feet-elevated oblique crunch","bp":"waist","eq":"stability ball","tg":"abs","mg":"abdominals","sm":["abdominals"],"st":["Begin by lying on your back on the ground with your feet and calves resting on a stability ball placed by your glutes. This is the starting position.","Place your arms crossed over your chest or hands behind your ears, ensuring not to pull on your head or neck.","Engage your core muscles and rotate your right shoulder towards your left knee. Lift your shoulder as high as you can while keeping your lower back connected to the ground. Focus on contracting your right oblique muscles.","Hold the position briefly at the top of the movement while squeezing your obliques.","Lower your torso back down to the starting position in a controlled manner.","Continue alternating crunches on each side for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_2d1f6c3d","n":"nordic hamstring curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Kneel on a padded surface, with your body upright and legs bent at a 90-degree angle at the knees.","Secure your lower legs or ankles under a sturdy object, or have a partner hold them down.","Cross your arms over your chest or place your hands on your thighs.","Engage your core and glutes to keep your body straight from your knees to your head.","Slowly lower your upper body towards the ground by extending your knees, keeping your torso straight.","Descend as far as you can control, ideally until your body is nearly parallel to the floor.","Use your hamstrings to pull your body back up to the starting position."],"src":"longhaul"},
{"id":"lh_567657bf","n":"barbell kneeling cuban rotation","bp":"shoulders","eq":"barbell","tg":"delts","mg":"forearms","sm":["forearms","shoulders"],"st":["Start in a tall kneeling position with your knees hip-width apart and your torso upright.","Hold a barbell with a wide, pronated grip (palms facing forward) in both hands over your head.","Lower the barbell towards your head by bending your elbows until your upper arms are parallel to the ground and your forearms are perpendicular to the ground. This is your starting position.","Slowly lower the barbell by rotating your shoulders forward, keeping your elbows as stationary as possible.","Pause briefly when your forearms have rotated parallel to the ground.","Rotate your shoulders backwards, slowly raising the barbell back to the starting position.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_d921179b","n":"kettlebell single-arm front rack contralateral walking lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","abdominals","calves","obliques","shoulders","traps"],"st":["Start standing with feet hip-width apart and a kettlebell in your right hand in a front rack position, resting the kettlebell on the back of your forearm with your elbow close to the body. This is your starting position.","Engage your core and brace your body, maintaining a neutral spine throughout the movement.","Step your left foot forward into a lunge position, ensuring your knee is aligned with your toe and creating a 90-degree angle at the knee joint.","Lower your right knee toward the ground without letting it touch, keeping your front knee stacked over your ankle.","Press through your left heel to return to the starting position, keeping the kettlebell stable in the front rack position.","Repeat for the desired number of repetitions walking forward with your left foot.","Switch sides to complete the same number of repetitions, holding the kettlebell with your left hand and walking forward with your right foot."],"src":"longhaul"},
{"id":"lh_efed36d3","n":"dumbbell front rack knee over toe split squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves","shoulders"],"st":["Select an appropriate pair of dumbbells and hold one in each hand.","Clean the dumbbells to the front rack position, resting one end of each dumbbell on your shoulders with your elbows pointed forward and your palms facing each other.","Position your feet in a split stance with one leg forward and the other leg behind you.","Align your front knee with your second to fourth toes, ensuring your knee travels over your toes throughout the movement.","Engage your core to maintain an upright torso and stabilize your position. This is your starting position.","Lower your body by bending both knees, ensuring the front knee tracks over the toes and the back knee approaches the ground.","Descend until the back knee is just above the ground and the front thigh is parallel to the floor.","Press through the heel of your front foot to return to the starting position.","Repeat the movement for the desired number of repetitions and then switch legs."],"src":"longhaul"},
{"id":"lh_b7e99b9f","n":"dumbbell single-arm bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","abdominals","calves","obliques"],"st":["Stand a few feet in front of a bench with your back towards it.","Hold a dumbbell in one hand on the same side as the working leg.","Extend your opposite leg back and place the top of your foot on the bench.","Keep your chest upright and core engaged throughout the movement.","Slowly lower your hips by bending the knee of the working leg.","Continue lowering until your front thigh is parallel to the ground.","Push through the heel of your front foot to return to the starting position.","Repeat for the desired number of repetitions before switching sides."],"src":"longhaul"},
{"id":"lh_04ccbbe0","n":"dumbbell one-handed overhead contralateral step-up","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","abdominals","calves","hamstrings","obliques","shoulders"],"st":["Stand in front of a step or bench with feet hip-width apart and a dumbbell in one hand.","Press the dumbbell overhead with the arm fully extended, keeping the core engaged.","Place the opposite foot on the step, ensuring the entire foot is on the platform.","Push through the heel of the foot on the step to lift your body up, while keeping the dumbbell arm extended overhead.","Bring the trailing leg up to join the lead on the step, achieving a balanced position.","Carefully step back down with the trailing leg first, followed by the lead leg.","Maintain control and balance throughout the movement, keeping the dumbbell overhead.","Repeat for desired reps, then switch arms and legs."],"src":"longhaul"},
{"id":"lh_eb253f9c","n":"dumbbell sumo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","inner thighs","calves","lower back"],"st":["Hold a dumbbell in front of your chest with both hands.","Stand with your feet wider than shoulder-width apart and toes pointed out at about a 45-degree angle.","Keep your chest up, back straight, and weight primarily on your heels. This is your starting position.","Bend your knees, keeping them in line with your toes, while lowerering your hips down until your thighs are at least parallel to the floor.","Push through your heels to extend your legs and return to the starting position."],"src":"longhaul"},
{"id":"lh_6fdbad68","n":"dumbbell one-handed suitcase walking lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","abdominals","calves","forearms","lower back","obliques","traps"],"st":["Stand upright with feet shoulder-width apart while holding a dumbbell in one hand by your side, similar to carrying a suitcase.","Keep your chest up, shoulders back, and core engaged.","Step forward with one leg into a lunge position, ensuring your front knee is directly above your ankle and your back knee is hovering just above the ground.","Push through the heel of your front foot to bring your back leg forward into the starting position, keeping the dumbbell steady by your side.","Continue the lunge by stepping forward with the opposite leg, maintaining balance and proper form.","Repeat the walking lunge series for the desired number of repetitions or distance while keeping the dumbbell in the same hand.","Switch the dumbbell to the other hand and repeat for balance after completing the set with one side."],"src":"longhaul"},
{"id":"lh_e251826a","n":"cable one-handed standing chest fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","abdominals","obliques","rotator cuff"],"st":["Adjust the cable machine pulley to shoulder height and attach a single handle.","Stand with your side facing the cable machine and grab the handle with your nearest hand.","Step away from the machine to create tension on the cable, feet shoulder-width apart and knees slightly bent for stability.","Straighten your arm with a slight bend in the elbow, positioning it parallel to the floor.","Brace your core and keep your hips and shoulders squared forward. This is your starting position.","Pull the handle just across your sternum, allowing your chest muscles to fully contract while keeping your arm slightly bent.","Slowly return the handle to the starting position while controlling the resistance.","Complete the desired number of repetitions and then switch sides."],"src":"longhaul"},
{"id":"lh_95ebb830","n":"isometric pull-up hold","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"lats","sm":["lats","rear deltoids","traps","abdominals","biceps","lower back","obliques"],"st":["Grasp the pull-up bar with an overhand grip slightly wider than shoulder-width apart.","Jump up or use a step to get into the top position of a pull-up with your chin above the bar.","Hold your body up with your chin above the bar, ensuring your core is tight and legs straight.","Keep your elbows bent and close to your body to engage the back muscles effectively.","Maintain the position as long as possible while breathing steadily."],"src":"longhaul"},
{"id":"lh_8646661d","n":"quadruped hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","abdominals"],"st":["Begin on your hands and knees in the quadruped position with hands under shoulders and knees under hips.","Engage your core and maintain a neutral spine throughout the exercise. This is your starting position.","Maintaining a bent knee, squeeze your glute and extend one foot towards the ceiling. Imagine placing your foot flat on the ceiling.","Squeeze your glutes at the top of the movement.","Lower the leg back to the starting position without touching the ground.","Perform the desired repetitions on one side before switching to the other leg."],"src":"longhaul"},
{"id":"lh_cffa970e","n":"dumbbell single-arm front rack walking lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","abdominals","calves","obliques","shoulders","traps"],"st":["Stand with feet hip-width apart holding a dumbbell in one hand at shoulder height, with your elbow close to your body, palm facing inward.","Engage your core to maintain balance and ensure your shoulders are level.","Step forward with the opposite leg to the dumbbell and lower your body into a lunge until both knees are at around 90-degree angles.","Ensure your front knee does not extend past your toes and your back knee hovers just above the ground.","Push off the front foot to bring your rear leg forward, coming back to the standing position.","Continue the movement by alternating legs as you walk forward, maintaining balance and control throughout.","Perform an even number of repetitions with the dumbbell in one hand before switching the dumbbell to the other hand and doing the same number of repetitions again."],"src":"longhaul"},
{"id":"lh_cec6c2d9","n":"single-leg romanian deadlift jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"glutes","sm":["glutes","hamstrings","quadriceps","abdominals","lower back"],"st":["Stand on your right leg, keeping a slight bend in the right knee. Bend your right arm in front of your chest and keep your left arm straight down by your side. This is your starting position.","Lean forward at your hips, extending your left leg behind you for balance. Keep your back straight, bend your left arm bent in front of your chest, and straighten your right arm behind you in rough alignment with your left leg.","Lower your torso and lift your left leg until your body forms a 'T' shape, or go as low as your flexibility allows.","Push through the heel of your right foot and prepare to explode upwards. Thrust your left arm down towards the ground while bringing your right arm up towards your chest to gain momentum for the jump.","Jump upwards, driving force through your right leg and using the motion of your arms to enhance the lift.","Land softly on your right leg, absorbing the impact with a slight bend in your knee, and reset your arms to their starting positions.","Repeat for the desired number of repetitions on one leg before switching to the other."],"src":"longhaul"},
{"id":"lh_173f0632","n":"landmine single-arm thruster","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","abdominals","lats","obliques","triceps"],"st":["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.","Stand with feet shoulder-width apart, holding the unattached end of the barbell with one hand at shoulder height. This is your starting position.","Perform a squat by pushing your hips back, keeping your chest up, and bending your knees until your thighs are parallel to the floor.","Explode upward from the squat position, using leg drive to assist in pressing the barbell overhead.","Extend your arm fully overhead while keeping the opposite arm by your side for balance.","Slowly lower the barbell back to shoulder height, controlling the descent, returning to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"src":"longhaul"},
{"id":"lh_25f02c2f","n":"forearm plank knee to elbow","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","chest","glutes","quadriceps","shoulders"],"st":["Begin in a forearm plank position with elbows directly beneath shoulders and body in a straight line from head to heels.","Engage core muscles and maintain a neutral spine position throughout the exercise. This is your starting position.","Lift one foot off the ground and bring the knee towards the same side elbow, maintaining plank position.","Return the foot back to the starting plank position.","Repeat the movement on the opposite side, bringing the other knee towards its respective elbow. This is one repetition.","Continue alternating knees to elbows while maintaining stability in the plank position."],"src":"longhaul"},
{"id":"lh_21da8c13","n":"cable rope skull crusher","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Begin by setting a flat bench in front of a cable machine with a low pulley.","Lie down on the bench with your head closest to the cable machine.","Grab the rope with an overhand grip, arms fully extended above your forehead. This is your starting position.","Ensure your elbows are shoulder-width apart and remain in a fixed position throughout the exercise.","Engage your core as you slowly lower the rope towards your forehead by bending your elbows.","Pause briefly once the rope is close to your forehead.","Press back to the starting position by extending your elbows and contracting your triceps.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_7e6139b5","n":"cable one-handed bayesian curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Stand facing away from a cable machine with the pulley set to the lowest height.","Select an appropriate weight on the machine for your fitness level.","Grip the handle attached to the cable with one hand, your palm facing forward.","Keep your feet shoulder-width apart, back straight, and shoulders back.","Curl the handle towards your chest, focusing on contracting the biceps while keeping your elbow stationary and close to your body.","Pause at the top of the curl to squeeze the bicep muscle intensely.","Slowly lower the handle back to the starting position, controlling the movement throughout the descent.","Repeat the movement for the desired number of repetitions before switching arms."],"src":"longhaul"},
{"id":"lh_9190bc6a","n":"kettlebell bottoms up seesaw overhead press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Stand with feet shoulder-width apart, holding a kettlebell in each hand by the horns on the floor between your legs.","Swing both kettlebells up, bending your elbows, so that the kettlebells end up in front of your shoulders in the bottoms-up position. This is your starting position.","Begin the press by pushing one kettlebell upward, over your head, until your arm is staight with a slight bend in the elbow.","Lower the raised kettlebell to your shoulder while simultaneously raising the lowered kettlebell over your head.","Alternate the press between the kettlebells in a seesaw motion, ensuring one is always moving up as the other moves down.","Complete the desired number of repetitions, ensuring that each hand pushes the kettlebell the same number of times, then safely lower both kettlebells to the ground."],"src":"longhaul"},
{"id":"lh_a1ea046d","n":"kettlebell front rack low switch cossack squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves","forearms","shoulders"],"st":["Begin with two kettlebells positioned on the floor in front of you.","Clean the kettlebells into a front rack position, with elbows tucked in and weights resting comfortably between your forearms and biceps.","Stand with feet wider than shoulder-width apart, toes slightly pointed out.","Shift your weight to your right leg, bending the right knee while keeping the left leg straight.","Lower your hips into a deep squat over your right leg, maintaining an upright torso. Your left toes may lift towards the ceiling, but keep both heels on the ground. This is your starting position.","Without standing up, shift your weight across to your left leg, bending your left knee while straightening your right leg similarly.","Transition the weight distribution smoothly towards the left leg.","Continue to alternate the weight shift from one leg to the other for the desired number of repetitions, maintaining a low squat position throughout the entire movement."],"src":"longhaul"},
{"id":"lh_8eca367b","n":"kettlebell alternating single-arm dead clean to push press","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","calves","hamstrings","lower back","triceps"],"st":["Stand with feet shoulder-width apart, a kettlebell in front of you.","Hinge at the hips and slightly bend your knees to grip the kettlebell with one hand, palm facing you.","Engage your core and drive through your heels to lift the kettlebell off the ground.","As you reach the top of the movement, quickly pull the kettlebell upwards, allowing it to rotate around your hand to the rack position at shoulder level.","From the rack position, bend your knees slightly in a quarter squat.","Explosively extend your legs and press the kettlebell overhead, rotating your wrist so your palm faces forward.","Reverse the press motion to return the kettlebell to the rack position.","Rotate the kettlebell back down to the starting position with control.","Switch hands and repeat the sequence on the opposite side."],"src":"longhaul"},
{"id":"lh_5c33d9e2","n":"kettlebell front rack march","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","calves","glutes","quadriceps"],"st":["Choose two kettlebells of the same weight.","Clean the kettlebells to your chest, tucking your elbows close to your body and holding the bells in front of your shoulders with your hands facing each other. This is your starting position.","Lift one knee to hip level and hold briefly, then lower it back to the ground.","Alternate lifting the other knee to the same level, maintaining balance and control.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_641dc09a","n":"barbell front rack curtsy lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","calves","hamstrings"],"st":["Position a barbell on a squat rack at shoulder height.","Stand facing the barbell, step under it, and rest it across the front of your shoulders.","Step back from the rack with the barbell in the front rack position.","Stand with feet hip-width apart, head up, and chest high. This is your starting position.","Take a step back and to the side with your right foot, crossing it behind your left leg.","Lower your body into a lunge, keeping your front knee aligned over your front foot and your core engaged.","Push through your front heel to rise, bringing your right foot back to the starting position.","Repeat for the desired number of repetitions and switch to the other side."],"src":"longhaul"},
{"id":"lh_2433e2f9","n":"dumbbell alternating tall kneeling arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"abdominals","sm":["abdominals","biceps","triceps"],"st":["Choose a pair of appropriate weights: dumbbells, kettlebells, etc.","Kneel on the ground with both knees, keeping your back straight and core engaged.","Hold the dumbbells in front of you at shoulder height, elbows bent, and palms facing your face. This is your starting position.","Rotate one arm outward, so your palm faces forward, and press the dumbbell overhead.","Bring the dumbbell back to the starting position while simultaneously rotating the other arm and pressing the dumbbell overhead.","Continue alternating arms, pressing one dumbbell overhead at a time.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_fb0607b9","n":"medicine ball seated rotational slam","bp":"waist","eq":"medicine ball","tg":"abs","mg":"obliques","sm":["obliques","lats","lower back","shoulders"],"st":["Sit with your feet extended in front of you, knees bent, and your feet or heels on the ground for stability. Hold the medicine ball with both hands near one hip. This is your starting position.","Begin the exercise by lifting the medicine ball in a circular motion on the same side, raising it up and over your head.","Continue the circular motion bringing the ball down with force on the opposite side.","Release the medicine ball towards the ground as you near the opposite hip from where you started, channeling maximum force through the slam.","Retrieve the medicine ball, return to the starting position on the opposite hip, and perform the exercise on the other side.","Repeat the exercise for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_20a7660d","n":"kettlebell horn grip bicep curl","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Choose an appropriate kettlebell weight. Hold it by the horns (sides of the handle) with both hands, palms facing each other. Stand with your feet shoulder-width apart. This is your starting position.","Keep your elbows close to your torso and slowly curl the kettlebell up towards your chest by bending your elbows.","Keep your upper arms stationary and only move your forearms.","Squeeze your biceps at the top of the movement.","Lower the kettlebell back to the starting position in a controlled manner.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_9589bd08","n":"double kettlebell swing and high pull","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"lower back","sm":["lower back","rear deltoids","shoulders","traps","forearms","hamstrings","lats","inner thighs"],"st":["Stand with your feet slightly wider than shoulder-width apart, toes slightly turned out.","Hinging forward, hold a kettlebell in each hand between your thighs, maintaining overhand grips, arms hanging naturally extended towards the floor.","Initiate the swing by snapping your hips forward, driving the kettlebell upward with your glutes and hamstrings. Maintain a flat back through the swing.","Push through your heels, pulling the kettlebells to chin height with elbows leading and flaring outward.","Pull your hands back towards your face at the top of the swing. Take care not to pull back so far that the kettlebells come too close to your face.","Return to the forward bend position by extending your arms at the elbows, hinging forward, and dropping the weights back down to the starting position between your legs and under your glutes in a controlled manner.","Repeat for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_e024e1f4","n":"band one-arm row lunge","bp":"upper legs","eq":"band","tg":"glutes","mg":"lats","sm":["lats","traps","quadriceps","calves"],"st":["Anchor a resistance band at the level of your belly button in front of you.","Grip the band with your target arm and start in a lunge position with the front leg opposite the target arm.","Simultaneously pull the band through a row motion while transitioning into a single leg stand on the front leg.","Raise the knee of the same side leg as the target arm to hip height as you pull the band, squeezing your back muscles.","Reverse the motion by lowering the knee and returning to the starting lunge position.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_1ba60d1d","n":"one-leg prone hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie down on your stomach with your arms extended out in front of you for support.","Engage your core to stabilize your lower back and minimize anterior pelvic tilt.","Lift one heel up towards the ceiling while keeping the knee straight and the foot flexed.","Hold the lifted position for 5-10 seconds, focusing on the contraction in the glutes and hamstrings.","Slowly lower your leg back down to the ground.","Repeat the movement on the same side for your desired number of repetitions, then switch to the other leg."],"src":"longhaul"},
{"id":"lh_c39f3233","n":"band drinking bird row","bp":"back","eq":"band","tg":"lats","mg":"lower back","sm":["lower back","traps","biceps","glutes","hamstrings"],"st":["Tie a resistance band down in front of you at sternum height and hold it with both hands using an overhand grip.","Stand with your feet shoulder-width apart and hinge at the hips forward while keeping your spine neutral and a slight bend in the knees.","Reach your hands out overhead as you hinge forward, maintaining tension in the band. This is your starting position.","Reverse the hinge and stand straight up while pulling the band towards your sternum, leading with your elbows.","Squeeze your back muscles as your hands reach your sternum and you're standing up straight.","Slowly return to the starting position by hinging forward at the hips again.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_ebe7c2ee","n":"standing clamshell","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"inner thighs","sm":["inner thighs"],"st":["Stand with your feet shoulder-width apart and place your hands together, in front of your face, for balance.","Lower your body by bending your knees until you're in a half-squat position.","Bring your knees close together, until they're almost touching. This is your starting position.","Rotate your knees outwards, away from your body, engaging your outer hips and glutes.","Hold the position for a moment, then slowly bring your knees back to the starting position.","Continue the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_15452318","n":"dumbbell one-leg front foot elevated split squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","calves","hamstrings","lower back"],"st":["Place a 12-16 inch plyobox in front of you and hold dumbbells of the desired weight.","Step onto the plyobox with your front foot, creating a split stance.","Engage your core and keep your chest lifted.","Lunge forward by bending the front foot's knee, allowing your back knee to lower towards the ground.","Lean forward slightly to allow your front knee to move past your toes, ensuring full knee flexion.","Push through your front heel to return to the standing position.","Repeat the movement for your desired number of repetitions then switch legs."],"src":"longhaul"},
{"id":"lh_4b66781b","n":"band hip hinge","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Place a resistance band around your hips and anchor it behind you at mid-hamstring level.","Stand with your feet hip-width apart and maintain a light bend in your knees. This is your starting position.","Engage your core and hinge forward at the hips, keeping your back straight and chest lifted.","Continue hinging until you feel a stretch in your hamstrings.","Pause briefly at the bottom, ensuring you maintain a neutral spine.","Stand straight back up to the starting position.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_3469dedf","n":"band seated half good morning","bp":"upper legs","eq":"band","tg":"glutes","mg":"lower back","sm":["lower back","abdominals","hamstrings","obliques"],"st":["Sit on an incline bench set at a 45-degree angle, facing the bench.","Loop a light monster band around both of your feet and run it across your upper back.","Maintain a neutral spine and hinge forward at the hips until your torso touches the pad of the bench.","Hinge backward to return to the neutral position.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_1c63130b","n":"prisoner squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","abdominals","calves","lower back"],"st":["Stand with your feet shoulder-width apart and toes pointing forward or slightly away from your body up to 15°.","Place your hands behind your head with your elbows pointing out to the sides. This is your starting position.","Bend your knees and lower your hips back and down as if sitting in a chair, keeping your weight on your heels.","Lower your body until your thighs are parallel to the ground.","Push through your heels to stand back up to the starting position.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_64288c96","n":"one-leg lying heel slide","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Lie down on your back on a padded surface with the target leg straight.","Wear a pair of socks or place a slider disc under the heel of the target leg. The goal is to be able to slide your heel on the floor.","Engage your core and keep your non-working leg bent with the foot flat on the floor. This is your starting position.","Slide your heel across the floor towards your buttocks, bending your knee as you go. Focus on contracting your hamstring on the sliding leg.","Slowly slide your heel back down to return to the straight leg position.","Repeat the movement for your desired number of repetitions then switch sides."],"src":"longhaul"},
{"id":"lh_69eeb08a","n":"dumbbell thumbs-up lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"shoulders","sm":["shoulders","traps"],"st":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a thumbs up grip (mid pronation).","Position your arms to your side and about 30 degrees in front of your body.","Engage your core and keep your elbows slightly bent. This is your starting position.","Raise the dumbbells to approximately shoulder height, focusing on using your shoulder muscles.","Pause briefly at the top of the movement.","Slowly lower the dumbbells back to the starting position with control.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_d7e410e4","n":"kettlebell one-leg kneeling bottoms-up hold","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Hold a kettlebell in your left hand.","Kneel with your left knee and right foot on the ground.","Raise the kettlebell by the handle so that you're balancing it upside-down.","Keep your elbow stacked directly below your wrist.","Flex your shoulder to 90 degrees and bend your elbow to 90 degrees.","Hold the kettlebell with your arm in this position for the desired amount of time.","Repeat the exercise on the other side from the same amount of time to complete a set."],"src":"longhaul"},
{"id":"lh_b055bb5a","n":"plate alternating side lunge pull","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","inner thighs","abdominals","calves","lower back"],"st":["Stand with a plate between your feet. This is your starting position.","Take a step to the side with one leg, bending that knee to lower your body into a side lunge.","Keep the other leg straight and your torso upright.","As you push through the heel of your bent leg to return to the standing position, use your non-planted leg to pull the weight plate inwards.","Continue pulling the plate inwards until you are fully standing with the plate close to your feet in the starting position.","Repeat the movement on the other side to complete a single repetition.","Continue for your desired number of repetitions, alternating legs with each lunge."],"src":"longhaul"},
{"id":"lh_444db891","n":"hand-release push-up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","abdominals","shoulders"],"st":["Assume the prone position with your body lying face-down on the ground. Place your hands flat on the ground, pointer fingers inside the outer edges of the shoulders. This is your starting position.","Push your whole body up from the ground as a single unit to the up position by fully extending the elbows.","Maintain a straight body alignment from the top of the head to the ankles throughout the movement.","Bend your elbows to lower your body all the way to the ground, ensuring chest, hips, and thighs touch down at the same time.","Lift your hands off the ground. Without moving the head, body, or legs, fully extend both arms into the T position until the arms are straight out to the side.","Immediately move your hands back on the ground to return to the starting position.","Repeat the movement for your desired number of repetitions."],"src":"longhaul"},
{"id":"lh_8b9e598d","n":"prone assisted neck bridge","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","traps"],"st":["Place a yoga or exercise mat on the floor for head padding.","Position the top of your head on the floor with your arms bent at the elbows, hands on the ground by both sides of your head, supporting your upper body.","Support your lower body by balancing on the balls of your toes.","Hinge at the hips to maintain a neutral spine throughout the movement.","Hold the bridge position for up to 8 seconds or as long as comfortable.","Lower your heels back down to the floor and extend your arms at the elbows to finish one repetition.","Repeat the exercise for the desired number of repetitions."],"src":"longhaul"},
{"id":"lh_d6dedfc6","n":"one-arm tabletop spine twist","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","rear deltoids","traps"],"st":["Kneel down and sit back onto your heels.","Place both elbows on the ground in front of you.","Raise one arm and place your hand behind your head.","Rotate your upper body towards the side with the raised arm, looking up.","Hold the stretch for the desired time.","Slowly return to the starting position.","Repeat the stretch for the same time on the other side."],"src":"longhaul"},
{"id":"lh_427cc63a","n":"one-leg wide lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Start in a plank or push-up position with both hands on the floor.","Step one foot forward, placing it just outside your hand on the same side.","Keep the back leg extended straight behind you with toes tucked under.","Lower your hips towards the floor to stretch the front leg's hamstrings and glutes. Your back knee may touch the floor.","Push your hips forward to stretch the hip flexors of the back leg.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_2488069d","n":"one-leg seated rock-paper-scissor toes","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Sit on a chair or on the floor. Raise one foot off the floor, holding the leg up by the raised knee.","Curl all toes to create the 'rock' position.","Return to neutral with toes relaxed.","Spread all toes apart into the 'paper' position.","Extend the big toe while keeping other toes curled for the 'scissors' position part one.","Curl the big toe and extend the other four toes for the 'scissors' position part two.","Continue alternating between the 'rock', 'paper', and both 'scissors' positions for the desired number of repetitions before switching to the other side."],"src":"longhaul"},
{"id":"lh_e84109f3","n":"foam roller one-leg seated knee-to-chest","bp":"upper legs","eq":"roller","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings","quadriceps"],"st":["Sit on the floor and place a foam roller behind your lower back.","Lean back slowly onto the foam roller, positioning it under your lumbar spine.","Hug one knee to your chest, keeping the other leg straight on the floor to avoid arching your lower back.","Find a tender spot and hold gentle pressure on it for the desired time. Hold each position instead of rolling.","Switch sides and hold the stretch for the same amount of time on the other leg."],"src":"longhaul"},
{"id":"lh_14216c38","n":"lacrosse ball seated calf massage","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["Sit on the floor and place a massage ball under your calf muscle.","Apply gentle pressure by pressing your leg down onto the ball.","Slowly flex your foot upward (dorsiflex) to stretch the calf while keeping pressure on the ball.","Then point your foot downward (plantarflex) to massage the calf.","Repeat the flexing and pointing movement slowly to massage the muscle.","Hold the massage for the desired time and switch to the other calf if needed."],"src":"longhaul"},
{"id":"lh_13ceed01","n":"one-arm front bend wall push","bp":"chest","eq":"body weight","tg":"pectorals","mg":"lats","sm":["lats","shoulders"],"st":["Stand facing a wall and place one hand flat against it at shoulder height.","Step back slightly and bend forward at the hips, keeping your arm straight and pressed into the wall.","Lift your arm upward along the wall to increase the stretch in the front of your shoulder.","Keep your back flat and your core engaged to avoid arching.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_4c141ddc","n":"one-leg lying ankle nerve floss","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Lie on your back on a padded surface with one thigh lifted to 90 degrees and supported by both both hands interlaced on the hamstring.","Keep the raised knee as straight as possible without causing nerve tension.","Keep the other leg straight and flat on the floor.","Simultaneously lift your head off the ground and at your chest while pointing your toes away from you (plantarflex).","Then, lower your head and look towards the ceiling while pulling your raised foot toward you (dorsiflex).","Repeat the movement for the desired number of repetitions then switch sides."],"src":"longhaul"},
{"id":"lh_300367c4","n":"dowel lying overhead shoulder rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Lie on your back holding a dowel with both hands above your chest, hands shoulder-width apart, with straight arms.","Lower the dowel over over your head by flexing your shoulders, keeping arms straight.","Hold the end range stretch for the desired amount of time."],"src":"longhaul"},
{"id":"lh_f4ee5779","n":"lacrosse ball neck twist","bp":"back","eq":"roller","tg":"traps","sm":[],"st":["Place a massage or lacrosse ball against the front and outer side of your neck.","Use your hand to gently compress the ball into the muscles.","Slowly rotate your head to the opposite side to increase the stretch on the neck.","Use small movements to massage the muscle group while maintaining gentle pressure.","Hold the massage and stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_bbc91bf3","n":"alternating lying chin tuck neck twist","bp":"back","eq":"body weight","tg":"traps","sm":[],"st":["Lie on your back with your forehead and chin parallel to the floor.","Tuck your chin in gently without lifting your head.","Rotate your neck slowly all the way to one side.","Return your head to center and rest briefly.","Rotate your neck all the way to the opposite side.","Return your head to center to complete one repetition.","Alternate the starting side with each new set.","Repeat the exercise for the desired amount of time or repetitions."],"src":"longhaul"},
{"id":"lh_d9905a13","n":"yoga block one-arm lying spine twist","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","chest","traps"],"st":["Lie on your side with your top leg supported by a yoga block or foam roller.","Extend both arms straight in front of you, palms together.","Lift your top arm up towards the ceiling while keeping your legs stable. Your gaze should follow the top arm while it travels.","Rotate your upper body, moving your top arm behind your back, face twisted towards the top arm, without lifting your leg off the support.","Hold the pose for the desired amount of time before repeating the exercise on the other side."],"src":"longhaul"},
{"id":"lh_6bb3cb8d","n":"one-leg lying outer thigh hip twist","bp":"upper legs","eq":"body weight","tg":"abductors","sm":[],"st":["Lie on your back with knees bent and feet flat on the floor.","Cross one ankle over the opposite thigh just above the knee.","Keep your upper back and shoulders pressed into the floor.","Slowly rotate your hips away from the crossed leg, letting the bottom thigh fall toward the floor.","Use the weight of the crossed leg to deepen the stretch in your outer hip.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_276b7bfb","n":"yoga block one-leg foot plank","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Place two yoga blocks on the floor and stand so one foot is supported on the blocks at the heel and toes.","Shift your weight onto the supported foot.","Allow the ball of your big toe to drop below the level of the yoga block.","Activate the muscles in your foot to lift the ball of your big toe back to a neutral position.","Hold the lifted position for 5 to 7 seconds.","Rest for the same amount of time.","Continue repetitions for the desired amount of time."],"src":"longhaul"},
{"id":"lh_935633d1","n":"one-arm lunging lower back wall twist","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","traps"],"st":["Start in a split squat position with your front leg against the wall, foot flat on the ground. Place your back leg's knee and toes on the ground.","Raise the arm on the same side as your front leg parallel to the ground in front of you. Keep the back of your hand and forearm in contact with the wall.","Rotate your torso slowly away from the front leg side, reaching your other arm back, parallel to the ground, to touch the back of that hand to the wall behind you.","Keep your hips facing forward and chest open as you rotate.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_b804c37e","n":"foam roller one-leg seated hamstring roll","bp":"upper legs","eq":"roller","tg":"hamstrings","sm":[],"st":["Sit on the floor and place a foam roller under one hamstring while placing the other leg's foot flat on the ground for stability.","Lean forward slightly to engage and stretch your hamstring.","Roll your leg back and forth on the foam roller to find tender spots.","When you find a tender spot, hold the position.","Hold the stretch for the desired time, then move to another spot or switch legs."],"src":"longhaul"},
{"id":"lh_d50d56d0","n":"one-leg elevated pigeon stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Place your front leg on an elevated surface, such as a bench, with the shin flat on the surface and the knee rotated outward from your hip.","Extend your back leg straight behind you on the ground.","Drop your front hip down toward the ground.","Support your upper body with your hands on the ground to maintain balance.","Keep your spine neutral and avoid leaning forward or back.","Take deep breaths, holding the stretch for the desired time, and switch sides."],"src":"longhaul"},
{"id":"lh_b3d157e7","n":"one-arm bicep wall stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"chest","sm":["chest","shoulders"],"st":["Raise one arm to shoulder height next to your body.","Rotate your wrist so your palm faces down.","Place your palm firmly against a doorframe, squat rack, or wall.","Twist your body away from your anchored arm to stretch your biceps.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_28f5b519","n":"segmental lower back flexion","bp":"back","eq":"body weight","tg":"traps","mg":"lower back","sm":["lower back"],"st":["Sit or stand with a neutral spine.","Flex your neck by bringing your chin towards your chest.","Slump your shoulders forward and flex your upper back.","Bend forward incrementally at each segment of the thoracic spine.","Continue the movement for the desired amount of time."],"src":"longhaul"},
{"id":"lh_3438f4cc","n":"bench one-leg incline reverse pigeon","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","inner thighs"],"st":["Set up an exercise bench at a 30 to 45 degree incline.","Place the shin of the leg you want to stretch on the inclined bench with the knee elevated above the foot.","Position the other leg behind you to support your bodyweight.","Drop the hip of the leg on the bench towards the ground and use your hands to support your body.","Keep your spine neutral to focus the stretch on your hips.","Hinge forward at the hips while maintaining a neutral spine to deepen the stretch.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_7bdfedb6","n":"one-leg seated pretzel stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Sit on a chair with your feet flat on the floor.","Place one ankle on the opposite knee by rotating the leg.","Push the folded knee towards the floor while leaning forward by hinging at the hips.","Keep the spine neutral to uncouple motion between the hip and back.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_017ff18f","n":"foam roller prone quad rolling","bp":"upper legs","eq":"roller","tg":"quads","sm":[],"st":["Lay down, facing the floor, on a foam roller placed on a tender spot on your quadriceps muscle.","Use your arms and other leg to control the amount of bodyweight you distribute on the foam roller.","Slowly flex and extend your knee to get an active massage.","Continue rolling and massaging the quadriceps for the desired amount of time."],"src":"longhaul"},
{"id":"lh_7a322044","n":"dowel shoulder teepee","bp":"shoulders","eq":"body weight","tg":"delts","mg":"shoulders","sm":["shoulders","triceps","biceps","forearms"],"st":["Grab a dowel or broomstick with hands wider than shoulder-width apart, holding it parallel to the ground in front of your waist.","Raise one end of the dowel above your head and then behind your back, keeping the other hand at hip level.","Lower the dowel so that it's parallel to the ground behind your back.","Raise the other hand to pull the dowel up and over your body bringing it parallel to the ground in front of you again.","Alternate directions, performing the same steps going the other direction.","Continue alternating the movement on each side for the desired amount of time."],"src":"longhaul"},
{"id":"lh_c814bdce","n":"seated crossed leg forward stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings","inner thighs"],"st":["Sit on the floor with your legs crossed.","Place your hands on the floor beside your hips.","Begin to lean forward, leading with your hands.","Crawl your hands forward to deepen the stretch.","Hold the stretch for the desired time while focusing on relaxed breaths."],"src":"longhaul"},
{"id":"lh_27d413a5","n":"yoga block one-leg bent knee calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Stand with one foot slightly ahead of the other as if you'd just taken one step forward.","Place your forward foot on a yoga block, in the loop of a kettlebell, or anything stable you can step on with the ball of your foot at ankle height. Ensure your heel remains on the ground.","Lean forward with both legs to create a stretch in the calf of the front leg.","Bend the knee of the front leg to target the soleus muscle in your calf.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_a84923d2","n":"overhead shrug neck rotation","bp":"back","eq":"body weight","tg":"traps","mg":"rear deltoids","sm":["rear deltoids","shoulders"],"st":["Raise both arms with your elbows straight overhead.","Shrug your shoulders upwards.","Slowly rotate your head and neck completely to one side without dropping the shoulders.","Rotate your head and neck completely to the opposite side.","Return to neutral cervical spine rotation.","Continue these rotations for the desired amount of time."],"src":"longhaul"},
{"id":"lh_e1d50b77","n":"front line opener","bp":"chest","eq":"body weight","tg":"pectorals","mg":"lower back","sm":["lower back","abdominals","shoulders"],"st":["Stand with your feet hip-width apart.","Bend forward, rounding your back and neck, tucking your chin. Tuck your chin and round your back far enough so that the crown of your head points directly in front of you.","Reach towards the floor with your arms internally rotated, touching the back of your wrists to each other in front of you.","Once you've reached your end range, extend your spine to straighten it and lift your chin to look directly in front.","As you're extending your spine, rotate your arms out and to your sides, palm facing forward, to open your chest muscles.","Continue repetitions for the desired amount of time."],"src":"longhaul"},
{"id":"lh_9057adbd","n":"band one-leg prone quad stretch","bp":"upper legs","eq":"band","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Loop a strength band or pull-up assist band around one ankle.","Lie down on your stomach.","Hold the band with both hands, over your back, over the same shoulder as the looped ankle, all the way until it's in front of your forehead as your lying down.","Pull the band away from your forehead to flex your quad.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_a1914245","n":"lacrosse ball one-leg seated calf release","bp":"lower legs","eq":"roller","tg":"calves","sm":[],"st":["Sit on a chair with both feet on the floor.","Lift your target leg and cross it over the other leg so that the target leg's ankle is resting on your other knee.","Place a massage ball on the inner part of your shin bone.","Apply pressure with the ball within tolerable limits.","Start with the ball at the midpoint of your shin and move down towards the foot 1 inch at a time.","Slowly and repeatedly rotate the ankle to point your foot towards the floor, then the ceiling, then back again to get an active release of the muscle.","Complete 3-5 slow repetitions per tender spot.","Continue the massage for the desired amount of time."],"src":"longhaul"},
{"id":"lh_74472297","n":"one-leg seated ankle crosses","bp":"lower legs","eq":"body weight","tg":"calves","sm":[],"st":["Sit on a chair or a stable surface with your legs on the ground.","Pull the target leg's knee towards your chest. Leave the other foot on the ground for stability.","You're going to draw a bowtie shape, '⋈', with your with the toes of your target leg.","Rotate your foot inwards and then outwards, exploring the full range of motion at the ankle.","After completing the bowtie shape in one direction, reverse the direction you're drawing with your foot.","Repeat the shape, forward and backward, for the desired amount of time and switch to target the other leg."],"src":"longhaul"},
{"id":"lh_052dc3b8","n":"hamstring floor sweep","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","rear deltoids"],"st":["Stand with one leg straight and extended in front of you, bending the other knee.","Hinge at the hips, keeping your back straight, and sweep the floor with your arms. Your arms should go in a sweeping motion from behind your back leg to the front of your straight, extended leg.","Step the front leg back, both feet side-by-side, and alternate sides by stepping forward with the opposite leg and bending the other knee.","Continue alternating sides and repeating the movement for the desired amount of time."],"src":"longhaul"},
{"id":"lh_4950e65b","n":"halo neck rotation","bp":"back","eq":"body weight","tg":"traps","sm":[],"st":["Stand or sit with your back straight and shoulders relaxed.","Keep your head looking straight forward.","Slowly move your neck to draw a halo with the tip of your head, moving it in a circular motion.","You can start by moving your head in a counter-clockwise direction, then switch to clockwise.","Continue the movement for the desired amount of time, ensuring you maintain the forward gaze throughout."],"src":"longhaul"},
{"id":"lh_0fe11f7f","n":"one-arm prone rotator cuff external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids"],"st":["Lie on your belly on a padded surface, such as a yoga mat.","Extend one arm out to the side, in line with your shoulder. Bend your elbow to a 90-degree angle to form a 'cactus' or 'goalpost' shape, with your forearm and palm resting on the floor.","Keep your elbow pinned to the floor, ensuring it stays in contact with the floor throughout the movement.","Rotate your hand towards the ceiling as high as possible, keeping the elbow pinned.","Hold the position for the desired time.","Repeat exercise on the other side."],"src":"longhaul"},
{"id":"lh_1a8dd353","n":"pillow kneeling reclining hero pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"inner thighs","sm":["inner thighs"],"st":["Kneel on a padded and stable surface.","Place a thick cushion or pillow directly behind you.","Sit on the floor with your bum between your feet.","Recline back with your upper body until your upper back is fully supported by the pillow.","Keep your arms straight overhead.","Hold the stretch for the desired time."],"src":"longhaul"},
{"id":"lh_0d629a34","n":"wrist extensor rotation stretch","bp":"lower arms","eq":"body weight","tg":"forearms","sm":[],"st":["Bend your hands at the wrists towards you. Place the back of your hands against a stable object like a bench or the floor with your body in a comfortable position that allows you to push down on your wrists.","Lean your body forwards to push the wrist into extension, staying within tolerable limits.","Rotate the elbows in and hold the stretch for up to 10 seconds.","Rotate the elbows out and hold the stretch for up to 10 seconds.","Continue alternating the movement on each side for the desired amount of time."],"src":"longhaul"},
{"id":"lh_c5547a33","n":"dowel one-arm posterior shoulder pull","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Stand tall with a dowel held behind your back using both hands.","Place one hand on the dowel at the small of your low back and the other hand behind your head on the dowel.","Use your top arm to gently pull the target hand up between your shoulder blades.","Hold the stretch for the desired amount of time and switch sides."],"src":"longhaul"},
{"id":"lh_4b67f7c5","n":"foam roller one-arm kneeling lower back wall sweep","bp":"back","eq":"roller","tg":"spine","mg":"abdominals","sm":["abdominals","obliques"],"st":["Start in a half kneel position by resting on one knee that's against a wall and the other leg in front of you with the foot place on the ground.","Place a foam roller or yoga block between your front knee and the wall and hold it in place.","Raise both hands behind your head and mesh your fingers.","Rotate your torso so that your chest faces away from the wall and your back is against the wall as much as possible.","Bend forwards through the torso, maintaining contact with the wall using your elbow that's closest to the wall, until you reach your end range, chest approaching the front knee.","Slide against the wall, reversing the movement, until you are once again upright.","Rotate through your torso until your chest faces the wall. Try to make the same elbow maintain contact with the wall throughout the movement.","Extend your spine towards your back leg as far as is comfortable for you.","Slide against the wall until you return to an upright position to complete a repetition.","Continue repetitions for the desired amount of time then switch to the other side."],"src":"longhaul"},
{"id":"lh_95a9db24","n":"lacrosse ball one-arm front shoulder active massage","bp":"shoulders","eq":"roller","tg":"delts","mg":"biceps","sm":["biceps","rotator cuff"],"st":["Stand with a massage ball in one hand and your other arm, the target arm, in a natural position hanging by your side.","Reach across your body to place a massage ball along a tender spot on the front of your target shoulder.","Pin the massage ball in place and compress it within tolerable limits.","Bend your target arm at the elbow so that there's a right angle between your upper and lower arm. This is your starting position.","Slowly extend your elbow behind you, keeping it close to your torso, to stretch your shoulder.","Lift your elbow away from your body about 45°.","Extend your arm in front of you, straightening the elbow, until you're comfortably reaching forward.","Return to the starting position, lowering your elbow close to your body, to complete the circlular motion and one repetition.","Continue repetitions for the desired amount of time."],"src":"longhaul"},
{"id":"lh_754f802f","n":"seated knee to heel taps","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"inner thighs","sm":["inner thighs","lower back","obliques","quadriceps"],"st":["Sit on the ground leaning backwards with your arms straight and your hands behind you.","Place your feet just wider than shoulder distance in front of you with your knees bent at 90° angles. This is your starting position.","Rotate one hip outwards until the knee of that leg reaches the ground.","Rotate the other hip inwards so that the knee of that leg touches the heel of the leg on the ground.","Return to the starting position and alternate sides.","Continue alternating the movement on each side for the desired amount of time."],"src":"longhaul"},
{"id":"lh_9810c307","n":"assisted wrist rotation","bp":"lower arms","eq":"body weight","tg":"forearms","sm":[],"st":["Raise your arms straight in front of you and clasp your hands together with your thumbs up and fingers interlaced.","Rotate your wrists together. Imagine tracing an infinity symbol (∞) with your knuckles. Aim for the largest rotation possible within tolerable limits.","Complete 5-8 repetitions in one direction (clockwise).","Switch direction (counter-clockwise) and repeat.","Continue alternating the movement in each direction for the desired amount of time."],"src":"longhaul"},
{"id":"lh_dbd57180","n":"one-leg kneeling couch quad stretch","bp":"upper legs","eq":"body weight","tg":"quads","sm":[],"st":["Stand in front of a couch, chair, or step stool.","Bend your right knee to place the top of your right foot on the surface behind you.","Bend your left knee to kneel to lower your body into a single-leg kneeling position.","Lower your body until you feel a comfortable stretch or your right knee rests on the floor.","Sit back towards your heel to increase the stretch in your quad.","Hold the stretch for the desired time and switch to the other side to complete a set."],"src":"longhaul"},
{"id":"lh_666c03d3","n":"hands-and-knees segmental cat cow","bp":"back","eq":"body weight","tg":"spine","mg":"abdominals","sm":["abdominals"],"st":["Get on your hands and knees on a padded surface, such as a gym mat or yoga mat.","Start from the tailbone and shift each vertebra up, towards the ceiling, one at a time. Continue to flex each segment through the lower, middle, and upper spine.","Once your full spine is in flexion, reverse the motion and push each vertebra, from the top of your spine to the bottom, towards the floor.","Continue alternating between flexion and extension for the desired amount of time."],"src":"longhaul"},
{"id":"lh_b1d2e640","n":"one-arm seated lower back rotation stretch","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","hamstrings","rear deltoids"],"st":["Sit on a stable surface with your legs extended in front of you.","Place your opposite forearm between both thighs.","Lean forward slightly and rotate your torso away from the side you want to stretch.","Reach your back arm towards the ceiling.","Use the arm between your thighs to provide additional leverage to assist in your rotation.","Hold the stretch for the desired time and switch to the other side."],"src":"longhaul"},
{"id":"lh_e430fead","n":"rowing","bp":"cardio","eq":"body weight","tg":"cardiovascular system","sm":[],"st":["Rowing is a full-body, low-impact cardiovascular exercise that engages multiple muscle groups including legs, arms, back, and core. It involves a synchronized motion on a rowing machine or in a boat, combining resistance and cardiovascular training to improve fitness and endurance. Suitable for indoor and outdoor settings, rowing offers a highly effective workout that enhances strength, cardiovascular health, and coordination, making it a comprehensive exercise choice for individuals of various fitness levels."],"src":"longhaul"},
{"id":"lh_1ff15091","n":"swimming","bp":"cardio","eq":"body weight","tg":"cardiovascular system","sm":[],"st":["Swimming is a full-body, low-impact exercise performed in water, encompassing various strokes like freestyle, breaststroke, backstroke, and butterfly. It engages multiple muscle groups, improves cardiovascular stamina, and enhances flexibility, all while providing buoyant support that minimizes stress on joints. Ideal for all ages and fitness levels, swimming offers both therapeutic and fitness benefits, making it a highly effective workout for overall health and conditioning."],"src":"longhaul"}
];
